/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/confederation/identifier
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_confederation_identifier_modify(struct nb_cb_modify_args *args)
{
	struct bgp *bgp;
	as_t confed_id;
	const char *as_pretty;
	char as_fallback[ASN_STRING_MAX_SIZE];

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	confed_id = yang_dnode_get_uint32(args->dnode, NULL);

	/*
	 * bgp_confederation_id_set's idempotency branch (cherry-picked from
	 * upstream dd4100e9a4) frees confed_id_pretty and XSTRDUPs as_str
	 * unconditionally — passing NULL there crashes.
	 *
	 * Prefer the user-provided pretty string from the sibling leaf (set
	 * by the bgp_confederation_identifier_cli DEFPY) so we preserve
	 * asplain vs asdot notation across config reloads. Fall back to a
	 * machine-formatted asn-as-string if the sibling isn't present (e.g.
	 * during partial config replay).
	 */
	if (yang_dnode_exists(args->dnode, "../identifier-pretty")) {
		as_pretty = yang_dnode_get_string(args->dnode,
						  "../identifier-pretty");
	} else {
		asn_asn2string(&confed_id, as_fallback, sizeof(as_fallback),
			       bgp->asnotation);
		as_pretty = as_fallback;
	}

	bgp_confederation_id_set(bgp, confed_id, as_pretty);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Set confederation identifier %u (pretty=%s) on AS %u",
			  confed_id, as_pretty, bgp->as);


	return NB_OK;
}


int routing_control_plane_protocols_control_plane_protocol_bgp_global_confederation_identifier_destroy(struct nb_cb_destroy_args *args)
{
	struct bgp *bgp;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	bgp_confederation_id_unset(bgp);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Cleared confederation identifier on AS %u",
			  bgp->as);


	return NB_OK;
}

/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/confederation/identifier-pretty
 *
 * Sibling string carrying the user's notation (asplain or asdot). When this
 * changes — e.g. user re-types `bgp confederation identifier 1.0` after
 * `bgp confederation identifier 65536` (same numeric, different notation) —
 * bgp_confederation_id_set's idempotency branch updates only the pretty
 * string and avoids any peer reset.
 */
int bgp_global_confederation_identifier_pretty_modify(struct nb_cb_modify_args *args)
{
	struct bgp *bgp;
	as_t confed_id;
	const char *as_pretty;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_OK;

	if (!yang_dnode_exists(args->dnode, "../identifier"))
		return NB_OK;

	confed_id = yang_dnode_get_uint32(args->dnode, "../identifier");
	as_pretty = yang_dnode_get_string(args->dnode, NULL);
	bgp_confederation_id_set(bgp, confed_id, as_pretty);
	return NB_OK;
}

int bgp_global_confederation_identifier_pretty_destroy(struct nb_cb_destroy_args *args)
{
	if (args->event != NB_EV_APPLY)
		return NB_OK;
	/* Destroy of pretty leaf is a no-op; the numeric `identifier` destroy
	 * callback (above) handles the actual unset via bgp_confederation_id_unset. */
	return NB_OK;
}

