/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/med-config/enable-med-admin
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_med_config_enable_med_admin_modify(struct nb_cb_modify_args *args)
{
	struct bgp *bgp;
	bool enable;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	enable = yang_dnode_get_bool(args->dnode, NULL);
	bgp->v_maxmed_admin = enable;

	if (enable && bgp->maxmed_admin_value == 0)
		bgp->maxmed_admin_value = BGP_MAXMED_VALUE_DEFAULT;

	bgp_maxmed_update(bgp);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Set max-med admin %s on AS %u",
			  enable ? "enabled" : "disabled", bgp->as);


	return NB_OK;
}


/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/med-config/max-med-admin
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_med_config_max_med_admin_modify(struct nb_cb_modify_args *args)
{
	struct bgp *bgp;
	uint32_t med_value;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	med_value = yang_dnode_get_uint32(args->dnode, NULL);

	/*
	 * YANG model uses value 0 to mean "disabled"
	 * Any non-zero value enables admin max-med
	 */
	if (med_value != 0) {
		bgp->v_maxmed_admin = 1;
		bgp->maxmed_admin_value = med_value;
	} else {
		bgp->v_maxmed_admin = BGP_MAXMED_ADMIN_UNCONFIGURED;
		bgp->maxmed_admin_value = BGP_MAXMED_VALUE_DEFAULT;
	}

	bgp_maxmed_update(bgp);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Set max-med admin value %u (enabled=%d) on AS %u",
			  med_value, bgp->v_maxmed_admin, bgp->as);


	return NB_OK;
}


