/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/route-reflector/route-reflector-cluster-id
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_route_reflector_route_reflector_cluster_id_modify(struct nb_cb_modify_args *args)
{
	struct bgp *bgp;
	struct in_addr cluster_id;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	yang_dnode_get_ipv4(&cluster_id, args->dnode, NULL);

	bgp_cluster_id_set(bgp, &cluster_id);
	bgp_clear_star_soft_out(NULL, bgp->name);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Set cluster-id %pI4 on AS %u",
			  &cluster_id, bgp->as);


	return NB_OK;
}


