/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/global-neighbor-config/labeled-unicast-explicit-null
 */
int bgp_global_labeled_unicast_explicit_null_modify(struct nb_cb_modify_args *args)
{
	struct bgp *bgp;
	const char *mode_str;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	mode_str = yang_dnode_get_string(args->dnode, NULL);

	/* Clear existing flags first */
	UNSET_FLAG(bgp->flags, BGP_FLAG_LU_IPV4_EXPLICIT_NULL);
	UNSET_FLAG(bgp->flags, BGP_FLAG_LU_IPV6_EXPLICIT_NULL);

	if (strcmp(mode_str, "ipv4-explicit-null") == 0) {
		SET_FLAG(bgp->flags, BGP_FLAG_LU_IPV4_EXPLICIT_NULL);
	} else if (strcmp(mode_str, "ipv6-explicit-null") == 0) {
		SET_FLAG(bgp->flags, BGP_FLAG_LU_IPV6_EXPLICIT_NULL);
	} else if (strcmp(mode_str, "explicit-null") == 0) {
		SET_FLAG(bgp->flags, BGP_FLAG_LU_IPV4_EXPLICIT_NULL);
		SET_FLAG(bgp->flags, BGP_FLAG_LU_IPV6_EXPLICIT_NULL);
	}
	/* "disabled" means no flags set, which is handled by clearing above */

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] labeled-unicast-explicit-null set to '%s' on AS %u",
			  mode_str, bgp->as);


	return NB_OK;
}

