/*
 * XPath: .../global/afi-safis/afi-safi/l2vpn-evpn/advertise-svi-ip
 */
int bgp_global_afi_safi_l2vpn_evpn_advertise_svi_ip_modify(struct nb_cb_modify_args *args)
{
	struct bgp *bgp;
	bool set;

	switch (args->event) {
	case NB_EV_VALIDATE:
	case NB_EV_PREPARE:
	case NB_EV_ABORT:
		break;
	case NB_EV_APPLY:
		bgp = nb_running_get_entry(args->dnode, NULL, true);
		if (!bgp)
			return NB_ERR_NOT_FOUND;

		set = yang_dnode_get_bool(args->dnode, NULL);
		if (set == bgp->evpn_info->advertise_svi_macip)
			break;
		bgp->evpn_info->advertise_svi_macip = set;
		bgp_zebra_advertise_svi_macip(bgp, set, 0);
		break;
	}

	return NB_OK;
}

