/*
 * XPath: .../global/afi-safis/afi-safi/l2vpn-link-state/distribute-bgp-fabric-link-state
 *
 * Toggle BGP-LS distribution for BGP-only fabrics (RFC draft
 * draft-ietf-idr-bgp-ls-bgp-only-fabric). On enable, sets
 * bgp->ls_info->enable_distribution and originates Node/Link/Prefix NLRIs
 * via bgp_ls_export_bgp_topology(). On destroy or disable, unsets the
 * flag and withdraws all locally originated NLRIs.
 *
 * Mirrors upstream bgp_ls_distribute_bgp_fabric DEFPY (master commit
 * e15218968f). The instance-id parameter from the upstream CLI is not
 * yet exposed via NB; defaults to 0 which matches the test config.
 */
int bgp_global_afi_safi_l2vpn_link_state_distribute_bgp_fabric_modify(struct nb_cb_modify_args *args)
{
	struct bgp *bgp;
	bool enable;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp || !bgp->ls_info)
		return NB_OK;

	enable = yang_dnode_get_bool(args->dnode, NULL);

	if (enable) {
		if (bgp->ls_info->enable_distribution)
			return NB_OK;
		bgp->ls_info->enable_distribution = true;
		bgp_ls_export_bgp_topology(bgp);
	} else {
		if (!bgp->ls_info->enable_distribution)
			return NB_OK;
		bgp->ls_info->enable_distribution = false;
		bgp->ls_info->instance_id = 0;
		bgp_ls_withdraw_all(bgp);
	}

	return NB_OK;
}

int bgp_global_afi_safi_l2vpn_link_state_distribute_bgp_fabric_destroy(struct nb_cb_destroy_args *args)
{
	struct bgp *bgp;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp || !bgp->ls_info)
		return NB_OK;

	if (!bgp->ls_info->enable_distribution)
		return NB_OK;

	bgp->ls_info->enable_distribution = false;
	bgp->ls_info->instance_id = 0;
	bgp_ls_withdraw_all(bgp);

	return NB_OK;
}

