/*
 * XPath: .../global/afi-safis/afi-safi/l2vpn-evpn/advertise-ipv4-unicast
 */
static void bgp_evpn_advertise_type5_apply(struct bgp *bgp, afi_t afi,
					   bool enable, bool gw_ip,
					   const char *rmap_name)
{
	safi_t safi = SAFI_UNICAST;
	uint32_t flag_normal, flag_gw_ip;

	if (afi == AFI_IP) {
		flag_normal = BGP_L2VPN_EVPN_ADV_IPV4_UNICAST;
		flag_gw_ip = BGP_L2VPN_EVPN_ADV_IPV4_UNICAST_GW_IP;
	} else {
		flag_normal = BGP_L2VPN_EVPN_ADV_IPV6_UNICAST;
		flag_gw_ip = BGP_L2VPN_EVPN_ADV_IPV6_UNICAST_GW_IP;
	}

	if (!enable) {
		/* Withdraw existing type-5 routes */
		if (CHECK_FLAG(bgp->af_flags[AFI_L2VPN][SAFI_EVPN],
			       flag_normal | flag_gw_ip))
			bgp_evpn_withdraw_type5_routes(bgp, afi, safi);

		if (CHECK_FLAG(bgp->af_flags[AFI_L2VPN][SAFI_EVPN], flag_gw_ip))
			bgp_addpath_type_changed(bgp);

		UNSET_FLAG(bgp->af_flags[AFI_L2VPN][SAFI_EVPN], flag_normal);
		UNSET_FLAG(bgp->af_flags[AFI_L2VPN][SAFI_EVPN], flag_gw_ip);

		/* Clear route-map */
		XFREE(MTYPE_ROUTE_MAP_NAME,
		      bgp->adv_cmd_rmap[afi][safi].name);
		route_map_counter_decrement(bgp->adv_cmd_rmap[afi][safi].map);
		bgp->adv_cmd_rmap[afi][safi].name = NULL;
		bgp->adv_cmd_rmap[afi][safi].map = NULL;
		return;
	}

	/* Withdraw first if changing mode */
	if (CHECK_FLAG(bgp->af_flags[AFI_L2VPN][SAFI_EVPN],
		       flag_normal | flag_gw_ip))
		bgp_evpn_withdraw_type5_routes(bgp, afi, safi);

	/* Set the appropriate flag */
	UNSET_FLAG(bgp->af_flags[AFI_L2VPN][SAFI_EVPN], flag_normal);
	UNSET_FLAG(bgp->af_flags[AFI_L2VPN][SAFI_EVPN], flag_gw_ip);
	if (gw_ip) {
		SET_FLAG(bgp->af_flags[AFI_L2VPN][SAFI_EVPN], flag_gw_ip);
		bgp_addpath_type_changed(bgp);
	} else {
		SET_FLAG(bgp->af_flags[AFI_L2VPN][SAFI_EVPN], flag_normal);
	}

	/* Set route-map */
	XFREE(MTYPE_ROUTE_MAP_NAME, bgp->adv_cmd_rmap[afi][safi].name);
	route_map_counter_decrement(bgp->adv_cmd_rmap[afi][safi].map);
	bgp->adv_cmd_rmap[afi][safi].name = NULL;
	bgp->adv_cmd_rmap[afi][safi].map = NULL;
	if (rmap_name) {
		bgp->adv_cmd_rmap[afi][safi].name =
			XSTRDUP(MTYPE_ROUTE_MAP_NAME, rmap_name);
		bgp->adv_cmd_rmap[afi][safi].map =
			route_map_lookup_by_name(rmap_name);
		route_map_counter_increment(bgp->adv_cmd_rmap[afi][safi].map);
	}

	/* Only advertise type-5 if L3VNI is configured and flags are set */
	if (advertise_type5_routes_bestpath(bgp, afi) ||
	    advertise_type5_routes_multipath(bgp, afi))
		bgp_evpn_advertise_type5_routes(bgp, afi, safi);
}

int bgp_global_afi_safi_l2vpn_evpn_advertise_ipv4_unicast_create(struct nb_cb_create_args *args)
{
	struct bgp *bgp;
	bool gw_ip;
	const char *rmap = NULL;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	gw_ip = yang_dnode_get_bool(args->dnode, "gateway-ip");
	if (yang_dnode_exists(args->dnode, "route-map"))
		rmap = yang_dnode_get_string(args->dnode, "route-map");

	bgp_evpn_advertise_type5_apply(bgp, AFI_IP, true, gw_ip, rmap);

	return NB_OK;
}

