int bgp_global_afi_safi_l2vpn_evpn_advertise_ipv4_unicast_gateway_ip_modify(struct nb_cb_modify_args *args)
{
	struct bgp *bgp;
	bool gw_ip;
	const char *rmap = NULL;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	/*
	 * Re-apply on gateway-ip toggle. The create callback only
	 * fires on first instantiation of the advertise-ipv4-unicast
	 * container; subsequent toggles of the gateway-ip leaf (e.g.
	 * test_bgp_evpn_rt5_addpath_transitions switching from
	 * `advertise ipv4 unicast gateway-ip` to
	 * `advertise ipv4 unicast`) only fire this modify callback,
	 * so we must call _apply here too or the
	 * BGP_L2VPN_EVPN_ADV_IPV4_UNICAST_GW_IP flag stays latched.
	 */
	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	gw_ip = yang_dnode_get_bool(args->dnode, NULL);
	if (yang_dnode_exists(args->dnode, "../route-map"))
		rmap = yang_dnode_get_string(args->dnode, "../route-map");

	bgp_evpn_advertise_type5_apply(bgp, AFI_IP, true, gw_ip, rmap);

	return NB_OK;
}

