/*
 * XPath: .../global/afi-safis/afi-safi/l2vpn-evpn/vrf-rd
 */
int bgp_global_afi_safi_l2vpn_evpn_vrf_rd_modify(struct nb_cb_modify_args *args)
{
	struct bgp *bgp;
	struct prefix_rd prd;
	const char *rd_str;

	switch (args->event) {
	case NB_EV_VALIDATE:
		rd_str = yang_dnode_get_string(args->dnode, NULL);
		if (!str2prefix_rd(rd_str, &prd)) {
			snprintf(args->errmsg, args->errmsg_len,
				 "Malformed Route Distinguisher: %s", rd_str);
			return NB_ERR_VALIDATION;
		}
		break;
	case NB_EV_PREPARE:
	case NB_EV_ABORT:
		break;
	case NB_EV_APPLY:
		bgp = nb_running_get_entry(args->dnode, NULL, true);
		if (!bgp)
			return NB_ERR_NOT_FOUND;

		rd_str = yang_dnode_get_string(args->dnode, NULL);
		str2prefix_rd(rd_str, &prd);

		/* Withdraw with old RD */
		if (CHECK_FLAG(bgp->vrf_flags, BGP_VRF_RD_CFGD))
			bgp_evpn_handle_vrf_rd_change(bgp, 1);

		bgp->vrf_prd = prd;
		XFREE(MTYPE_BGP, bgp->vrf_prd_pretty);
		bgp->vrf_prd_pretty = XSTRDUP(MTYPE_BGP, rd_str);
		SET_FLAG(bgp->vrf_flags, BGP_VRF_RD_CFGD);

		/* Re-advertise with new RD */
		bgp_evpn_handle_vrf_rd_change(bgp, 0);
		break;
	}
	return NB_OK;
}

int bgp_global_afi_safi_l2vpn_evpn_vrf_rd_destroy(struct nb_cb_destroy_args *args)
{
	struct bgp *bgp;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	if (!CHECK_FLAG(bgp->vrf_flags, BGP_VRF_RD_CFGD))
		return NB_OK;

	bgp_evpn_handle_vrf_rd_change(bgp, 1);
	UNSET_FLAG(bgp->vrf_flags, BGP_VRF_RD_CFGD);
	bgp_evpn_derive_auto_rd_for_vrf(bgp);
	bgp_evpn_handle_vrf_rd_change(bgp, 0);

	return NB_OK;
}

/*
 * XPath: .../global/afi-safis/afi-safi/l2vpn-evpn/vrf-route-target
 */
int bgp_global_afi_safi_l2vpn_evpn_vrf_route_target_create(struct nb_cb_create_args *args)
{
	struct bgp *bgp;
	const char *rt_str;
	const char *dir_str;
	struct ecommunity *ecom = NULL;
	bool is_wildcard = false;

	rt_str = yang_dnode_get_string(args->dnode, "rt-value");

	if (args->event == NB_EV_VALIDATE) {
		if (rt_str[0] == '*') {
			char buf[64];
			snprintf(buf, sizeof(buf), "0%s", rt_str + 1);
			ecom = ecommunity_str2com(buf, ECOMMUNITY_ROUTE_TARGET, 0);
		} else {
			ecom = ecommunity_str2com(rt_str, ECOMMUNITY_ROUTE_TARGET, 0);
		}
		if (!ecom) {
			snprintf(args->errmsg, args->errmsg_len,
				 "Failed to parse VRF route-target rt-value '%s'",
				 rt_str);
			return NB_ERR_VALIDATION;
		}
		ecommunity_free(&ecom);
		return NB_OK;
	}

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	dir_str = yang_dnode_get_string(args->dnode, "direction");

	/* Handle wildcard RT */
	if (rt_str[0] == '*') {
		is_wildcard = true;
		char buf[64];
		snprintf(buf, sizeof(buf), "0%s", rt_str + 1);
		ecom = ecommunity_str2com(buf, ECOMMUNITY_ROUTE_TARGET, 0);
	} else {
		ecom = ecommunity_str2com(rt_str, ECOMMUNITY_ROUTE_TARGET, 0);
	}

	if (!ecom) {
		zlog_warn("BGP NB: vrf-route-target create APPLY: parse of rt-value '%s' failed unexpectedly (already passed VALIDATE)",
			  rt_str);
		return NB_OK;
	}

	if (strcmp(dir_str, "import") == 0)
		bgp_evpn_configure_import_rt_for_vrf(bgp, ecom, is_wildcard);
	else
		bgp_evpn_configure_export_rt_for_vrf(bgp, ecom);


	return NB_OK;
}

int bgp_global_afi_safi_l2vpn_evpn_vrf_route_target_destroy(struct nb_cb_destroy_args *args)
{
	struct bgp *bgp;
	const char *rt_str;
	const char *dir_str;
	struct ecommunity *ecom = NULL;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_OK;

	rt_str = yang_dnode_get_string(args->dnode, "rt-value");
	dir_str = yang_dnode_get_string(args->dnode, "direction");

	if (rt_str[0] == '*') {
		char buf[64];
		snprintf(buf, sizeof(buf), "0%s", rt_str + 1);
		ecom = ecommunity_str2com(buf, ECOMMUNITY_ROUTE_TARGET, 0);
	} else {
		ecom = ecommunity_str2com(rt_str, ECOMMUNITY_ROUTE_TARGET, 0);
	}

	if (!ecom) {
		zlog_warn("BGP NB: vrf-route-target destroy APPLY: parse of rt-value '%s' failed; skipping unconfigure",
			  rt_str);
		return NB_OK;
	}

	if (strcmp(dir_str, "import") == 0)
		bgp_evpn_unconfigure_import_rt_for_vrf(bgp, ecom);
	else
		bgp_evpn_unconfigure_export_rt_for_vrf(bgp, ecom);

	ecommunity_free(&ecom);

	return NB_OK;
}

