/*
 * XPath: .../global/afi-safis/afi-safi/l2vpn-evpn/vni
 */
int bgp_global_afi_safi_l2vpn_evpn_vni_create(struct nb_cb_create_args *args)
{
	struct bgp *bgp;
	vni_t vni;
	struct bgpevpn *vpn;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	vni = yang_dnode_get_uint32(args->dnode, "vni-number");
	vpn = bgp_evpn_lookup_vni(bgp, vni);
	if (!vpn) {
		struct ipaddr origip = {};
		struct in_addr mcast = {};

		/* Check if this L2VNI is already configured as L3VNI */
		if (bgp_evpn_lookup_l3vni_l2vni_table(vni)) {
			flog_err(EC_BGP_VNI,
				 "%u: Failed to create L2VNI %u, it is configured as L3VNI",
				 bgp->vrf_id, vni);
			return NB_ERR_RESOURCE;
		}

		/* Set originator IP from router-id */
		SET_IPADDR_V4(&origip);
		origip.ipaddr_v4 = bgp->router_id;

		vpn = bgp_evpn_new(bgp, vni, &origip,
				   0, mcast, 0);
		if (!vpn)
			return NB_ERR_RESOURCE;
	}

	SET_FLAG(vpn->flags, VNI_FLAG_CFGD);
	nb_running_set_entry(args->dnode, vpn);

	return NB_OK;
}

int bgp_global_afi_safi_l2vpn_evpn_vni_destroy(struct nb_cb_destroy_args *args)
{
	struct bgp *bgp;
	struct bgpevpn *vpn;

	switch (args->event) {
	case NB_EV_VALIDATE:
	case NB_EV_PREPARE:
	case NB_EV_ABORT:
		break;
	case NB_EV_APPLY:
		bgp = nb_running_get_entry(lyd_parent(args->dnode), NULL, true);
		vpn = nb_running_unset_entry(args->dnode);
		if (!bgp || !vpn)
			return NB_OK;

		if (!is_vni_live(vpn)) {
			bgp_evpn_free(bgp, vpn);
			break;
		}

		/* VNI is live — unconfigure each parameter before freeing.
		 * Matches baseline evpn_delete_vni() logic.
		 */
		UNSET_FLAG(vpn->flags, VNI_FLAG_CFGD);

		/* First, deal with the export side - RD and export RT */
		if (is_rd_configured(vpn)) {
			if (is_vni_live(vpn))
				bgp_evpn_handle_rd_change(bgp, vpn, 1);
			bgp_evpn_derive_auto_rd(bgp, vpn);
			if (is_vni_live(vpn))
				bgp_evpn_handle_rd_change(bgp, vpn, 0);
		}
		if (is_export_rt_configured(vpn))
			evpn_unconfigure_export_rt(bgp, vpn, NULL);

		/* Next, deal with the import side */
		if (is_import_rt_configured(vpn))
			evpn_unconfigure_import_rt(bgp, vpn, NULL);
		break;
	}
	return NB_OK;
}

/*
 * XPath: .../global/afi-safis/afi-safi/l2vpn-evpn/vni/rd
 */
int bgp_global_afi_safi_l2vpn_evpn_vni_rd_modify(struct nb_cb_modify_args *args)
{
	struct bgp *bgp;
	struct bgpevpn *vpn;
	struct prefix_rd prd;
	const char *rd_str;

	switch (args->event) {
	case NB_EV_VALIDATE:
		rd_str = yang_dnode_get_string(args->dnode, NULL);
		if (!str2prefix_rd(rd_str, &prd)) {
			snprintf(args->errmsg, args->errmsg_len,
				 "Malformed Route Distinguisher: %s", rd_str);
			return NB_ERR_VALIDATION;
		}
		break;
	case NB_EV_PREPARE:
	case NB_EV_ABORT:
		break;
	case NB_EV_APPLY:
		vpn = nb_running_get_entry(lyd_parent(args->dnode), NULL, true);
		bgp = nb_running_get_entry(lyd_parent(lyd_parent(args->dnode)),
					   NULL, true);
		if (!bgp || !vpn)
			return NB_ERR_NOT_FOUND;

		rd_str = yang_dnode_get_string(args->dnode, NULL);
		str2prefix_rd(rd_str, &prd);

		if (CHECK_FLAG(vpn->flags, VNI_FLAG_RD_CFGD))
			bgp_evpn_handle_rd_change(bgp, vpn, 1);

		vpn->prd = prd;
		XFREE(MTYPE_BGP, vpn->prd_pretty);
		vpn->prd_pretty = XSTRDUP(MTYPE_BGP, rd_str);
		SET_FLAG(vpn->flags, VNI_FLAG_RD_CFGD);

		bgp_evpn_handle_rd_change(bgp, vpn, 0);
		break;
	}
	return NB_OK;
}

int bgp_global_afi_safi_l2vpn_evpn_vni_rd_destroy(struct nb_cb_destroy_args *args)
{
	struct bgp *bgp;
	struct bgpevpn *vpn;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	vpn = nb_running_get_entry(lyd_parent(args->dnode), NULL, true);
	bgp = nb_running_get_entry(lyd_parent(lyd_parent(args->dnode)),
				   NULL, true);
	if (!bgp || !vpn)
		return NB_OK;

	if (!CHECK_FLAG(vpn->flags, VNI_FLAG_RD_CFGD))
		return NB_OK;

	bgp_evpn_handle_rd_change(bgp, vpn, 1);
	UNSET_FLAG(vpn->flags, VNI_FLAG_RD_CFGD);
	bgp_evpn_derive_auto_rd(bgp, vpn);
	bgp_evpn_handle_rd_change(bgp, vpn, 0);

	return NB_OK;
}

