/*
 * BMP monitor policy helper - used by all pre-policy/post-policy/loc-rib callbacks.
 * Walks up to the bmp_targets stored at the target-list node.
 */
static int bmp_monitor_policy_modify(struct nb_cb_modify_args *args,
				     afi_t afi, safi_t safi, uint8_t flag)
{
	void *bt;
	bool enable;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bt = nb_running_get_entry(args->dnode, NULL, true);
	enable = yang_dnode_get_bool(args->dnode, NULL);
	if (bmp_nb_cb && bmp_nb_cb->monitor_set)
		bmp_nb_cb->monitor_set(bt, afi, safi, flag, enable);

	return NB_OK;
}

