/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/afi-safis/afi-safi
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_create(struct nb_cb_create_args *args)
{
	struct bgp *bgp;
	const char *afi_safi_name;
	afi_t afi;
	safi_t safi;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	afi_safi_name = yang_dnode_get_string(args->dnode,
					      "./afi-safi-name");
	yang_afi_safi_identity2value(afi_safi_name, &afi, &safi);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] AFI-SAFI %s (afi=%d, safi=%d) created on AS %u",
			  afi_safi_name, afi, safi, bgp->as);


	return NB_OK;
}



int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_destroy(struct nb_cb_destroy_args *args)
{
	struct bgp *bgp;
	const char *afi_safi_name;
	afi_t afi;
	safi_t safi;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_OK;

	afi_safi_name = yang_dnode_get_string(args->dnode,
					      "./afi-safi-name");
	yang_afi_safi_identity2value(afi_safi_name, &afi, &safi);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] AFI-SAFI %s (afi=%d, safi=%d) destroyed on AS %u",
			  afi_safi_name, afi, safi, bgp->as);


	return NB_OK;
}

/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/afi-safis/afi-safi/ipv4-unicast/network-config
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv4_unicast_network_config_create(struct nb_cb_create_args *args)
{
	struct bgp *bgp;
	const char *prefix_str;
	struct prefix p;
	struct bgp_dest *dest;
	struct bgp_static *bgp_static;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	/* lyd_parent to skip stale entry stored at this dnode on delta re-commit; see 993754e18a */
	bgp = nb_running_get_entry(lyd_parent(args->dnode), NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	prefix_str = yang_dnode_get_string(args->dnode, "./prefix");
	if (str2prefix(prefix_str, &p) == 0)
		return NB_ERR_VALIDATION;
	apply_mask(&p);

	if (!bgp->static_routes[AFI_IP][SAFI_UNICAST])
		return NB_ERR_NOT_FOUND;

	dest = bgp_node_get(bgp->static_routes[AFI_IP][SAFI_UNICAST], &p);
	bgp_static = bgp_dest_get_bgp_static_info(dest);

	if (!bgp_static) {
		bgp_static = XCALLOC(MTYPE_BGP_STATIC,
				     sizeof(struct bgp_static));
		bgp_static->valid = 1;
		bgp_static->label_index = BGP_INVALID_LABEL_INDEX;
		bgp_dest_set_bgp_static_info(dest, bgp_static);
	}

	nb_running_set_entry(args->dnode, bgp_static);

	/*
	 * Don't call bgp_static_update() here - it will be called
	 * in the apply_finish callback after all child properties
	 * (route-map, backdoor, label-index) are set.
	 */

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Created network %s on AS %u",
			  prefix_str, bgp->as);


	return NB_OK;
}

/*
 * apply_finish callback for network-config.
 * Called after all child nodes (route-map, backdoor, label-index) are processed.
 * This is where we call bgp_static_update() to install the route with all
 * properties set atomically.
 */
void routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv4_unicast_network_config_apply_finish(struct nb_cb_apply_finish_args *args)
{
	struct bgp_static *bgp_static;
	struct bgp *bgp;
	const char *prefix_str;
	struct prefix p;
	const struct lyd_node *bgp_dnode;

	bgp_static = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp_static)
		return;

	bgp_dnode = yang_dnode_get_parent(args->dnode, "bgp");
	bgp = nb_running_get_entry(bgp_dnode, NULL, true);
	if (!bgp)
		return;

	prefix_str = yang_dnode_get_string(args->dnode, "./prefix");
	if (str2prefix(prefix_str, &p) == 0)
		return;
	apply_mask(&p);

	bgp_static_update(bgp, &p, bgp_static, AFI_IP, SAFI_UNICAST);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Updated network %s on AS %u",
			   prefix_str, bgp->as);
}


int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv4_unicast_network_config_destroy(struct nb_cb_destroy_args *args)
{
	struct bgp *bgp;
	const char *prefix_str;
	struct prefix p;
	struct bgp_dest *dest;
	struct bgp_static *bgp_static;
	const struct lyd_node *bgp_dnode;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	/* Get BGP instance via parent dnode - the current dnode has bgp_static set */
	bgp_dnode = yang_dnode_get_parent(args->dnode, "bgp");
	if (!bgp_dnode)
		return NB_OK;
	bgp = nb_running_get_entry(bgp_dnode, NULL, true);
	if (!bgp)
		return NB_OK;

	prefix_str = yang_dnode_get_string(args->dnode, "./prefix");
	if (str2prefix(prefix_str, &p) == 0)
		return NB_OK;
	apply_mask(&p);

	if (!bgp->static_routes[AFI_IP][SAFI_UNICAST])
		return NB_OK;

	dest = bgp_node_lookup(bgp->static_routes[AFI_IP][SAFI_UNICAST], &p);
	if (!dest)
		return NB_OK;

	bgp_static = bgp_dest_get_bgp_static_info(dest);
	if (bgp_static) {
		bgp_static_withdraw(bgp, &p, AFI_IP, SAFI_UNICAST, NULL);
		bgp_dest_set_bgp_static_info(dest, NULL);
		XFREE(MTYPE_BGP_STATIC, bgp_static);
	}

	nb_running_unset_entry(args->dnode);
	bgp_dest_unlock_node(dest);
	bgp_dest_unlock_node(dest);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Removed network %s from AS %u",
			  prefix_str, bgp->as);


	return NB_OK;
}

