/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/afi-safis/afi-safi/ipv4-unicast/network-config/rmap-policy-export
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv4_unicast_network_config_rmap_policy_export_modify(struct nb_cb_modify_args *args)
{
	struct bgp_static *bgp_static;
	const char *rmap_name;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp_static = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp_static)
		return NB_ERR_NOT_FOUND;

	rmap_name = yang_dnode_get_string(args->dnode, NULL);

	XFREE(MTYPE_ROUTE_MAP_NAME, bgp_static->rmap.name);
	route_map_counter_decrement(bgp_static->rmap.map);
	bgp_static->rmap.name = XSTRDUP(MTYPE_ROUTE_MAP_NAME, rmap_name);
	bgp_static->rmap.map = route_map_lookup_by_name(rmap_name);
	route_map_counter_increment(bgp_static->rmap.map);

	/* Re-process the static route with the new route-map */
	{
		const struct lyd_node *bgp_dnode =
			yang_dnode_get_parent(args->dnode, "bgp");
		struct bgp *bgp =
			nb_running_get_entry(bgp_dnode, NULL, true);
		const char *prefix_str =
			yang_dnode_get_string(args->dnode, "../prefix");
		struct prefix p;

		if (bgp && str2prefix(prefix_str, &p)) {
			apply_mask(&p);
			bgp_static_update(bgp, &p, bgp_static, AFI_IP,
					  SAFI_UNICAST);
		}
	}

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Set network route-map=%s", rmap_name);


	return NB_OK;
}


