/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/afi-safis/afi-safi/ipv4-unicast/aggregate-route/origin
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv4_unicast_aggregate_route_origin_modify(struct nb_cb_modify_args *args)
{
	struct bgp_aggregate *aggregate;
	const char *origin_str;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	aggregate = nb_running_get_entry(args->dnode, NULL, true);
	if (!aggregate)
		return NB_ERR_NOT_FOUND;

	origin_str = yang_dnode_get_string(args->dnode, NULL);
	if (strcmp(origin_str, "igp") == 0)
		aggregate->origin = BGP_ORIGIN_IGP;
	else if (strcmp(origin_str, "egp") == 0)
		aggregate->origin = BGP_ORIGIN_EGP;
	else if (strcmp(origin_str, "incomplete") == 0)
		aggregate->origin = BGP_ORIGIN_INCOMPLETE;
	else
		aggregate->origin = BGP_ORIGIN_UNSPECIFIED;

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Set aggregate origin=%s", origin_str);


	return NB_OK;
}


/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/afi-safis/afi-safi/ipv4-unicast/aggregate-route/match-med
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv4_unicast_aggregate_route_match_med_modify(struct nb_cb_modify_args *args)
{
	struct bgp *bgp;
	struct bgp_aggregate *aggregate;
	const char *prefix_str;
	struct prefix p;
	bool match_med;
	const struct lyd_node *bgp_dnode;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	aggregate = nb_running_get_entry(args->dnode, NULL, true);
	if (!aggregate)
		return NB_ERR_NOT_FOUND;

	match_med = yang_dnode_get_bool(args->dnode, NULL);
	aggregate->match_med = match_med;

	/* Get BGP instance via parent nodes and trigger aggregate update */
	bgp_dnode = yang_dnode_get_parent(args->dnode, "bgp");
	if (bgp_dnode) {
		bgp = nb_running_get_entry(bgp_dnode, NULL, true);
		prefix_str = yang_dnode_get_string(args->dnode, "../prefix");
		if (bgp && prefix_str && str2prefix(prefix_str, &p)) {
			apply_mask(&p);
			bgp_aggregate_route(bgp, &p, AFI_IP, SAFI_UNICAST, aggregate);

			/*
			 * If MEDs mismatch and summary_only is enabled,
			 * routes may have been incorrectly suppressed
			 * before match_med was set. Unsuppress them now.
			 */
			if (match_med && aggregate->med_mismatched &&
			    aggregate->summary_only)
				bgp_aggregate_toggle_suppressed(
					aggregate, bgp, &p, AFI_IP,
					SAFI_UNICAST, false);
		}
	}

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Set aggregate match-med=%d", aggregate->match_med);


	return NB_OK;
}


/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/afi-safis/afi-safi/ipv4-unicast/aggregate-route/suppress-map
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv4_unicast_aggregate_route_suppress_map_modify(struct nb_cb_modify_args *args)
{
	struct bgp *bgp;
	struct bgp_aggregate *aggregate;
	const char *map_name;
	const char *prefix_str;
	struct prefix p;
	const struct lyd_node *bgp_dnode;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	aggregate = nb_running_get_entry(args->dnode, NULL, true);
	if (!aggregate)
		return NB_ERR_NOT_FOUND;

	map_name = yang_dnode_get_string(args->dnode, NULL);

	XFREE(MTYPE_ROUTE_MAP_NAME, aggregate->suppress_map_name);
	route_map_counter_decrement(aggregate->suppress_map);
	aggregate->suppress_map_name =
		XSTRDUP(MTYPE_ROUTE_MAP_NAME, map_name);
	aggregate->suppress_map = route_map_lookup_by_name(map_name);
	route_map_counter_increment(aggregate->suppress_map);

	/* Get BGP instance and trigger aggregate update */
	bgp_dnode = yang_dnode_get_parent(args->dnode, "bgp");
	if (bgp_dnode) {
		bgp = nb_running_get_entry(bgp_dnode, NULL, true);
		prefix_str = yang_dnode_get_string(args->dnode, "../prefix");
		if (bgp && prefix_str && str2prefix(prefix_str, &p)) {
			apply_mask(&p);
			bgp_aggregate_route(bgp, &p, AFI_IP, SAFI_UNICAST, aggregate);
		}
	}


	return NB_OK;
}


int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv4_unicast_aggregate_route_suppress_map_destroy(struct nb_cb_destroy_args *args)
{
	struct bgp_aggregate *aggregate;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	aggregate = nb_running_get_entry(args->dnode, NULL, true);
	if (!aggregate)
		return NB_OK;

	XFREE(MTYPE_ROUTE_MAP_NAME, aggregate->suppress_map_name);
	route_map_counter_decrement(aggregate->suppress_map);
	aggregate->suppress_map = NULL;


	return NB_OK;
}

