/* Forward declaration - defined before rt-list callbacks */
static int yang_rt_to_ecommunity(const char *yang_rt, char *ec_rt, size_t ec_rt_size);

/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/afi-safis/afi-safi/ipv4-unicast/vpn-config/import-rt-list
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv4_unicast_vpn_config_import_rt_list_create(struct nb_cb_create_args *args)
{
	struct bgp *bgp;
	const char *rt_yang;
	char rt_ec[128];
	struct ecommunity *ecom_new = NULL;

	switch (args->event) {
	case NB_EV_VALIDATE:
	case NB_EV_PREPARE:
	case NB_EV_ABORT:
		return NB_OK;
	case NB_EV_APPLY:
		bgp = nb_running_get_entry(args->dnode, NULL, true);
		if (!bgp)
			return NB_ERR_NOT_FOUND;

		rt_yang = yang_dnode_get_string(args->dnode, NULL);
		if (yang_rt_to_ecommunity(rt_yang, rt_ec, sizeof(rt_ec)) < 0)
			return NB_ERR_VALIDATION;

		ecom_new = ecommunity_str2com(rt_ec, ECOMMUNITY_ROUTE_TARGET, 0);
		if (!ecom_new)
			return NB_ERR_VALIDATION;

		vpn_leak_prechange(BGP_VPN_POLICY_DIR_FROMVPN, AFI_IP,
				   bgp_get_default(), bgp);

		if (bgp->vpn_policy[AFI_IP].rtlist[BGP_VPN_POLICY_DIR_FROMVPN])
			bgp->vpn_policy[AFI_IP].rtlist[BGP_VPN_POLICY_DIR_FROMVPN] =
				ecommunity_merge(bgp->vpn_policy[AFI_IP].rtlist[BGP_VPN_POLICY_DIR_FROMVPN],
						 ecom_new);
		else
			bgp->vpn_policy[AFI_IP].rtlist[BGP_VPN_POLICY_DIR_FROMVPN] =
				ecommunity_dup(ecom_new);

		vpn_leak_postchange(BGP_VPN_POLICY_DIR_FROMVPN, AFI_IP,
				    bgp_get_default(), bgp);
		ecommunity_free(&ecom_new);
		return NB_OK;
	}

	return NB_OK;
}


int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv4_unicast_vpn_config_import_rt_list_destroy(struct nb_cb_destroy_args *args)
{
	struct bgp *bgp;
	const char *rt_yang;
	char rt_ec[ECOMMUNITY_STRLEN];
	struct ecommunity *ecom_del;

	switch (args->event) {
	case NB_EV_VALIDATE:
	case NB_EV_PREPARE:
	case NB_EV_ABORT:
		return NB_OK;
	case NB_EV_APPLY:
		bgp = nb_running_get_entry(args->dnode, NULL, true);
		if (!bgp)
			return NB_ERR_NOT_FOUND;

		rt_yang = yang_dnode_get_string(args->dnode, NULL);
		if (yang_rt_to_ecommunity(rt_yang, rt_ec, sizeof(rt_ec)) < 0)
			return NB_OK;

		ecom_del = ecommunity_str2com(rt_ec, ECOMMUNITY_ROUTE_TARGET, 0);
		if (!ecom_del)
			return NB_OK;

		vpn_leak_prechange(BGP_VPN_POLICY_DIR_FROMVPN, AFI_IP,
				   bgp_get_default(), bgp);

		if (bgp->vpn_policy[AFI_IP].rtlist[BGP_VPN_POLICY_DIR_FROMVPN]) {
			ecommunity_del_val(
				bgp->vpn_policy[AFI_IP].rtlist[BGP_VPN_POLICY_DIR_FROMVPN],
				(struct ecommunity_val *)ecom_del->val);
			if (bgp->vpn_policy[AFI_IP].rtlist[BGP_VPN_POLICY_DIR_FROMVPN]->size == 0) {
				ecommunity_free(&bgp->vpn_policy[AFI_IP].rtlist[BGP_VPN_POLICY_DIR_FROMVPN]);
				bgp->vpn_policy[AFI_IP].rtlist[BGP_VPN_POLICY_DIR_FROMVPN] = NULL;
			}
		}

		vpn_leak_postchange(BGP_VPN_POLICY_DIR_FROMVPN, AFI_IP,
				    bgp_get_default(), bgp);
		ecommunity_free(&ecom_del);
		return NB_OK;
	}

	return NB_OK;
}

