/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/afi-safis/afi-safi/ipv6-unicast/network-config/rmap-policy-export
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv6_unicast_network_config_rmap_policy_export_modify(struct nb_cb_modify_args *args)
{
	struct bgp_static *bgp_static;
	const char *rmap_name;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp_static = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp_static)
		return NB_ERR_NOT_FOUND;

	rmap_name = yang_dnode_get_string(args->dnode, NULL);
	XFREE(MTYPE_ROUTE_MAP_NAME, bgp_static->rmap.name);
	route_map_counter_decrement(bgp_static->rmap.map);
	bgp_static->rmap.name = XSTRDUP(MTYPE_ROUTE_MAP_NAME, rmap_name);
	bgp_static->rmap.map = route_map_lookup_by_name(rmap_name);
	route_map_counter_increment(bgp_static->rmap.map);

	/* Re-process the static route with the new route-map */
	{
		const struct lyd_node *bgp_dnode =
			yang_dnode_get_parent(args->dnode, "bgp");
		struct bgp *bgp =
			nb_running_get_entry(bgp_dnode, NULL, true);
		const char *prefix_str =
			yang_dnode_get_string(args->dnode, "../prefix");
		struct prefix p;

		if (bgp && str2prefix(prefix_str, &p)) {
			apply_mask(&p);
			bgp_static_update(bgp, &p, bgp_static, AFI_IP6,
					  SAFI_UNICAST);
		}
	}


	return NB_OK;
}


int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv6_unicast_network_config_rmap_policy_export_destroy(struct nb_cb_destroy_args *args)
{
	struct bgp_static *bgp_static;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp_static = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp_static)
		return NB_ERR_NOT_FOUND;

	XFREE(MTYPE_ROUTE_MAP_NAME, bgp_static->rmap.name);
	route_map_counter_decrement(bgp_static->rmap.map);
	bgp_static->rmap.map = NULL;

	/* Re-process the static route without the route-map */
	{
		const struct lyd_node *bgp_dnode =
			yang_dnode_get_parent(args->dnode, "bgp");
		struct bgp *bgp =
			nb_running_get_entry(bgp_dnode, NULL, true);
		const char *prefix_str =
			yang_dnode_get_string(args->dnode, "../prefix");
		struct prefix p;

		if (bgp && str2prefix(prefix_str, &p)) {
			apply_mask(&p);
			bgp_static_update(bgp, &p, bgp_static, AFI_IP6,
					  SAFI_UNICAST);
		}
	}


	return NB_OK;
}

/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/afi-safis/afi-safi/ipv6-unicast/aggregate-route
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv6_unicast_aggregate_route_create(struct nb_cb_create_args *args)
{
	struct bgp *bgp;
	const char *prefix_str;
	struct prefix p;
	struct bgp_dest *dest;
	struct bgp_aggregate *aggregate;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	/* lyd_parent to skip stale entry stored at this dnode on delta re-commit; see 993754e18a */
	bgp = nb_running_get_entry(lyd_parent(args->dnode), NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	/* Create aggregate table if it doesn't exist */
	if (!bgp->aggregate[AFI_IP6][SAFI_UNICAST])
		bgp->aggregate[AFI_IP6][SAFI_UNICAST] =
			bgp_table_init(bgp, AFI_IP6, SAFI_UNICAST);

	prefix_str = yang_dnode_get_string(args->dnode, "./prefix");
	if (str2prefix(prefix_str, &p) == 0)
		return NB_ERR_VALIDATION;
	apply_mask(&p);

	dest = bgp_node_get(bgp->aggregate[AFI_IP6][SAFI_UNICAST], &p);
	aggregate = bgp_dest_get_bgp_aggregate_info(dest);

	if (!aggregate) {
		aggregate = XCALLOC(MTYPE_BGP_AGGREGATE,
				    sizeof(struct bgp_aggregate));
		aggregate->origin = BGP_ORIGIN_UNSPECIFIED;
		bgp_dest_set_bgp_aggregate_info(dest, aggregate);
	}

	nb_running_set_entry(args->dnode, aggregate);

	bgp_aggregate_route(bgp, &p, AFI_IP6, SAFI_UNICAST, aggregate);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Created IPv6 aggregate-address %s on AS %u",
			  prefix_str, bgp->as);


	return NB_OK;
}


int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv6_unicast_aggregate_route_destroy(struct nb_cb_destroy_args *args)
{
	struct bgp *bgp;
	const char *prefix_str;
	struct prefix p;
	struct bgp_dest *dest;
	struct bgp_aggregate *aggregate;
	const struct lyd_node *bgp_dnode;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	/*
	 * Get the aggregate from this node's running entry,
	 * then get BGP from the parent bgp node.
	 */
	aggregate = nb_running_get_entry(args->dnode, NULL, false);

	bgp_dnode = yang_dnode_get_parent(args->dnode, "bgp");
	if (!bgp_dnode)
		return NB_OK;

	bgp = nb_running_get_entry(bgp_dnode, NULL, true);
	if (!bgp)
		return NB_OK;

	/* Check if aggregate table exists */
	if (!bgp->aggregate[AFI_IP6][SAFI_UNICAST])
		return NB_OK;

	prefix_str = yang_dnode_get_string(args->dnode, "./prefix");
	if (str2prefix(prefix_str, &p) == 0)
		return NB_OK;
	apply_mask(&p);

	dest = bgp_node_lookup(bgp->aggregate[AFI_IP6][SAFI_UNICAST], &p);
	if (!dest)
		return NB_OK;

	if (aggregate) {
		bgp_aggregate_delete(bgp, &p, AFI_IP6, SAFI_UNICAST,
				     aggregate);
		bgp_aggregate_install(bgp, AFI_IP6, SAFI_UNICAST, &p, 0,
				      NULL, NULL, NULL, NULL, 0,
				      aggregate);
		bgp_dest_set_bgp_aggregate_info(dest, NULL);
		bgp_aggregate_free(aggregate);
	}

	nb_running_unset_entry(args->dnode);
	bgp_dest_unlock_node(dest);
	bgp_dest_unlock_node(dest);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Destroyed IPv6 aggregate-address %s on AS %u",
			  prefix_str, bgp->as);


	return NB_OK;
}

