/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/afi-safis/afi-safi/ipv6-unicast/aggregate-route/summary-only
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv6_unicast_aggregate_route_summary_only_modify(struct nb_cb_modify_args *args)
{
	struct bgp *bgp;
	struct bgp_aggregate *aggregate;
	const char *prefix_str;
	struct prefix p;
	bool summary_only;
	const struct lyd_node *bgp_dnode;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	aggregate = nb_running_get_entry(args->dnode, NULL, true);
	if (!aggregate)
		return NB_ERR_NOT_FOUND;

	summary_only = yang_dnode_get_bool(args->dnode, NULL);
	aggregate->summary_only = summary_only ? 1 : 0;

	bgp_dnode = yang_dnode_get_parent(args->dnode, "bgp");
	if (bgp_dnode) {
		bgp = nb_running_get_entry(bgp_dnode, NULL, true);
		prefix_str = yang_dnode_get_string(args->dnode, "../prefix");
		if (bgp && prefix_str && str2prefix(prefix_str, &p)) {
			apply_mask(&p);
			bgp_aggregate_route(bgp, &p, AFI_IP6, SAFI_UNICAST, aggregate);
		}
	}

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Set IPv6 aggregate summary-only=%d",
			  aggregate->summary_only);


	return NB_OK;
}


