/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/afi-safis/afi-safi/ipv6-unicast/route-flap-dampening/enable
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv6_unicast_route_flap_dampening_enable_modify(struct nb_cb_modify_args *args)
{
	struct bgp *bgp;
	struct bgp_damp_config *bdc;
	bool enable;
	time_t half, max;
	unsigned int reuse, suppress;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	enable = yang_dnode_get_bool(args->dnode, NULL);
	if (enable) {
		bdc = &bgp->damp[AFI_IP6][SAFI_UNICAST];
		half = bdc->half_life ? bdc->half_life
				      : DEFAULT_HALF_LIFE * 60;
		reuse = bdc->reuse_limit ? bdc->reuse_limit
					 : DEFAULT_REUSE;
		suppress = bdc->suppress_value ? bdc->suppress_value
					       : DEFAULT_SUPPRESS;
		max = bdc->max_suppress_time ? bdc->max_suppress_time
					     : half * 4;
		bgp_damp_enable(bgp, AFI_IP6, SAFI_UNICAST, half, reuse,
				suppress, max);
	} else {
		bgp_damp_disable(bgp, AFI_IP6, SAFI_UNICAST);
	}


	return NB_OK;
}


