/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/afi-safis/afi-safi/ipv6-unicast/redistribution-list
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv6_unicast_redistribution_list_create(struct nb_cb_create_args *args)
{
	struct bgp *bgp;
	const char *route_type_str;
	int route_type;
	uint16_t route_instance;
	struct bgp_redist *red;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	/* lyd_parent to skip stale entry stored at this dnode on delta re-commit; see 993754e18a */
	bgp = nb_running_get_entry(lyd_parent(args->dnode), NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	route_type_str = yang_dnode_get_string(args->dnode,
					       "./route-type");
	route_type = proto_redistnum(AFI_IP6, route_type_str);
	if (route_type < 0)
		return NB_ERR_VALIDATION;

	route_instance = yang_dnode_get_uint16(args->dnode,
					       "./route-instance");

	red = bgp_redist_add(bgp, AFI_IP6, route_type, route_instance);
	bgp_redistribute_set(bgp, AFI_IP6, route_type, route_instance,
			     false);

	nb_running_set_entry(args->dnode, red);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Created IPv6 redistribution %s instance %u on AS %u",
			  route_type_str, route_instance, bgp->as);


	return NB_OK;
}


int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv6_unicast_redistribution_list_destroy(struct nb_cb_destroy_args *args)
{
	struct bgp *bgp;
	const char *route_type_str;
	const char *vrf_name;
	int route_type;
	uint16_t route_instance;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	/* Get VRF name from parent control-plane-protocol and look up
	 * BGP instance directly. This is more reliable than using
	 * nb_running_get_entry with a relative path.
	 */
	vrf_name = yang_dnode_get_string(args->dnode,
					 "../../../../../../vrf");
	if (strcmp(vrf_name, VRF_DEFAULT_NAME) == 0)
		bgp = bgp_get_default();
	else
		bgp = bgp_lookup_by_name(vrf_name);
	if (!bgp)
		return NB_OK;

	route_type_str = yang_dnode_get_string(args->dnode,
					       "./route-type");
	route_type = proto_redistnum(AFI_IP6, route_type_str);
	if (route_type < 0)
		return NB_OK;

	route_instance = yang_dnode_get_uint16(args->dnode,
					       "./route-instance");

	bgp_redistribute_unset(bgp, AFI_IP6, route_type, route_instance);

	nb_running_unset_entry(args->dnode);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Destroyed IPv6 redistribution %s instance %u",
			  route_type_str, route_instance);


	return NB_OK;
}

/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/afi-safis/afi-safi/ipv6-unicast/redistribution-list/metric
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv6_unicast_redistribution_list_metric_modify(struct nb_cb_modify_args *args)
{
	struct bgp *bgp;
	struct bgp_redist *red;
	const struct lyd_node *bgp_dnode;
	const char *route_type_str;
	int route_type;
	uint32_t metric;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	red = nb_running_get_entry(args->dnode, NULL, true);
	if (!red)
		return NB_ERR_NOT_FOUND;

	bgp_dnode = yang_dnode_get_parent(args->dnode, "bgp");
	if (!bgp_dnode)
		return NB_ERR_NOT_FOUND;
	bgp = nb_running_get_entry(bgp_dnode, NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;
	route_type_str = yang_dnode_get_string(args->dnode,
					       "../route-type");
	route_type = proto_redistnum(AFI_IP6, route_type_str);
	metric = yang_dnode_get_uint32(args->dnode, NULL);

	bgp_redistribute_metric_set(bgp, red, AFI_IP6, route_type,
				    metric);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Set IPv6 redistribution metric=%u", metric);


	return NB_OK;
}


