/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/afi-safis/afi-safi/ipv6-unicast/vpn-config/rd
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv6_unicast_vpn_config_rd_modify(struct nb_cb_modify_args *args)
{
	struct bgp *bgp;
	const char *rd_str;
	struct prefix_rd prd;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	rd_str = yang_dnode_get_string(args->dnode, NULL);
	if (str2prefix_rd(rd_str, &prd) == 0)
		return NB_ERR_VALIDATION;

	vpn_leak_prechange(BGP_VPN_POLICY_DIR_TOVPN, AFI_IP6,
			   bgp_get_default(), bgp);

	if (bgp->vpn_policy[AFI_IP6].tovpn_rd_pretty &&
	    strmatch(rd_str, bgp->vpn_policy[AFI_IP6].tovpn_rd_pretty))
		return NB_OK;

	bgp_route_distinguisher_update_notify(bgp, AFI_IP6, true);

	XFREE(MTYPE_BGP_NAME, bgp->vpn_policy[AFI_IP6].tovpn_rd_pretty);
	bgp->vpn_policy[AFI_IP6].tovpn_rd_pretty =
		XSTRDUP(MTYPE_BGP_NAME, rd_str);
	bgp->vpn_policy[AFI_IP6].tovpn_rd = prd;
	SET_FLAG(bgp->vpn_policy[AFI_IP6].flags,
		 BGP_VPN_POLICY_TOVPN_RD_SET);
	SET_FLAG(bgp->vpn_policy[AFI_IP6].flags,
		 BGP_VPN_POLICY_TOVPN_RD_CLI_SET);

	bgp_route_distinguisher_update_notify(bgp, AFI_IP6, false);

	vpn_leak_postchange(BGP_VPN_POLICY_DIR_TOVPN, AFI_IP6,
			    bgp_get_default(), bgp);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Set IPv6 VPN RD=%s on AS %u", rd_str, bgp->as);


	return NB_OK;
}


int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv6_unicast_vpn_config_rd_destroy(struct nb_cb_destroy_args *args)
{
	struct bgp *bgp;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_OK;

	vpn_leak_prechange(BGP_VPN_POLICY_DIR_TOVPN, AFI_IP6,
			   bgp_get_default(), bgp);

	bgp_route_distinguisher_update_notify(bgp, AFI_IP6, true);

	XFREE(MTYPE_BGP_NAME, bgp->vpn_policy[AFI_IP6].tovpn_rd_pretty);
	bgp->vpn_policy[AFI_IP6].tovpn_rd_pretty = NULL;
	UNSET_FLAG(bgp->vpn_policy[AFI_IP6].flags,
		   BGP_VPN_POLICY_TOVPN_RD_SET);
	UNSET_FLAG(bgp->vpn_policy[AFI_IP6].flags,
		   BGP_VPN_POLICY_TOVPN_RD_CLI_SET);

	bgp_route_distinguisher_update_notify(bgp, AFI_IP6, false);

	vpn_leak_postchange(BGP_VPN_POLICY_DIR_TOVPN, AFI_IP6,
			    bgp_get_default(), bgp);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Cleared IPv6 VPN RD");


	return NB_OK;
}

