/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/afi-safis/afi-safi/ipv6-unicast/table-map
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv6_unicast_table_map_modify(struct nb_cb_modify_args *args)
{
	struct bgp *bgp;
	const char *rmap_name;
	struct bgp_rmap *rmap;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	rmap_name = yang_dnode_get_string(args->dnode, NULL);
	rmap = &bgp->table_map[AFI_IP6][SAFI_UNICAST];

	XFREE(MTYPE_ROUTE_MAP_NAME, rmap->name);
	route_map_counter_decrement(rmap->map);
	rmap->name = XSTRDUP(MTYPE_ROUTE_MAP_NAME, rmap_name);
	rmap->map = route_map_lookup_by_name(rmap_name);
	route_map_counter_increment(rmap->map);

	bgp_zebra_announce_table(bgp, AFI_IP6, SAFI_UNICAST);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Set IPv6 unicast table-map %s",
			  rmap_name);


	return NB_OK;
}


