/*
 * Helper: shared body for nexthop-prefer-global modify across IPv6 SAFIs.
 * Mirrors baseline DEFPY bgp_af_nexthop_prefer_global: when value changes,
 * update bgp->nexthop_prefer_global[AFI_IP6][safi] and call
 * bgp_clear_soft_in() to re-evaluate received UPDATEs.
 */
static int bgp_nb_nexthop_prefer_global_modify(struct nb_cb_modify_args *args, safi_t safi)
{
	struct bgp *bgp;
	bool enable;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	enable = yang_dnode_get_bool(args->dnode, NULL);
	if (bgp->nexthop_prefer_global[AFI_IP6][safi] == enable)
		return NB_OK;

	bgp->nexthop_prefer_global[AFI_IP6][safi] = enable;
	bgp_clear_soft_in(bgp, AFI_IP6, safi);
	return NB_OK;
}

static int bgp_nb_nexthop_prefer_global_destroy(struct nb_cb_destroy_args *args, safi_t safi)
{
	struct bgp *bgp;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_OK;

	if (bgp->nexthop_prefer_global[AFI_IP6][safi]) {
		bgp->nexthop_prefer_global[AFI_IP6][safi] = false;
		bgp_clear_soft_in(bgp, AFI_IP6, safi);
	}
	return NB_OK;
}

/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/afi-safis/afi-safi/ipv6-unicast/nexthop-prefer-global
 */
int bgp_global_afi_safi_ipv6_unicast_nexthop_prefer_global_modify(struct nb_cb_modify_args *args)
{
	return bgp_nb_nexthop_prefer_global_modify(args, SAFI_UNICAST);
}

int bgp_global_afi_safi_ipv6_unicast_nexthop_prefer_global_destroy(struct nb_cb_destroy_args *args)
{
	return bgp_nb_nexthop_prefer_global_destroy(args, SAFI_UNICAST);
}

