/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/afi-safis/afi-safi/ipv4-multicast/network-config
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv4_multicast_network_config_create(struct nb_cb_create_args *args)
{
	struct bgp *bgp;
	const char *prefix_str;
	struct prefix p;
	struct bgp_dest *dest;
	struct bgp_static *bgp_static;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	/* lyd_parent to skip stale entry stored at this dnode on delta re-commit; see 993754e18a */
	bgp = nb_running_get_entry(lyd_parent(args->dnode), NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	prefix_str = yang_dnode_get_string(args->dnode, "./prefix");
	if (str2prefix(prefix_str, &p) == 0)
		return NB_ERR_VALIDATION;
	apply_mask(&p);

	dest = bgp_node_get(bgp->static_routes[AFI_IP][SAFI_MULTICAST], &p);
	bgp_static = bgp_dest_get_bgp_static_info(dest);

	if (!bgp_static) {
		bgp_static = XCALLOC(MTYPE_BGP_STATIC,
				     sizeof(struct bgp_static));
		bgp_static->valid = 1;
		bgp_static->label_index = BGP_INVALID_LABEL_INDEX;
		bgp_dest_set_bgp_static_info(dest, bgp_static);
	}

	nb_running_set_entry(args->dnode, bgp_static);

	/* Set route-map if specified before calling bgp_static_update */
	if (yang_dnode_exists(args->dnode, "./rmap-policy-export")) {
		const char *rmap_name = yang_dnode_get_string(
			args->dnode, "./rmap-policy-export");
		XFREE(MTYPE_ROUTE_MAP_NAME, bgp_static->rmap.name);
		route_map_counter_decrement(bgp_static->rmap.map);
		bgp_static->rmap.name =
			XSTRDUP(MTYPE_ROUTE_MAP_NAME, rmap_name);
		bgp_static->rmap.map = route_map_lookup_by_name(rmap_name);
		route_map_counter_increment(bgp_static->rmap.map);
	}

	/* Set label-index if specified */
	if (yang_dnode_exists(args->dnode, "./label-index"))
		bgp_static->label_index =
			yang_dnode_get_uint32(args->dnode, "./label-index");

	bgp_static_update(bgp, &p, bgp_static, AFI_IP, SAFI_MULTICAST);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Created IPv4 multicast network %s on AS %u",
			  prefix_str, bgp->as);


	return NB_OK;
}


int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv4_multicast_network_config_destroy(struct nb_cb_destroy_args *args)
{
	struct bgp *bgp;
	const char *prefix_str;
	struct prefix p;
	struct bgp_dest *dest;
	struct bgp_static *bgp_static;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	bgp = nb_running_get_entry(args->dnode, NULL, true);
	if (!bgp)
		return NB_OK;

	prefix_str = yang_dnode_get_string(args->dnode, "./prefix");
	if (str2prefix(prefix_str, &p) == 0)
		return NB_OK;
	apply_mask(&p);

	dest = bgp_node_lookup(bgp->static_routes[AFI_IP][SAFI_MULTICAST], &p);
	if (!dest)
		return NB_OK;

	bgp_static = bgp_dest_get_bgp_static_info(dest);
	if (bgp_static) {
		bgp_static_withdraw(bgp, &p, AFI_IP, SAFI_MULTICAST, NULL);
		bgp_dest_set_bgp_static_info(dest, NULL);
		XFREE(MTYPE_BGP_STATIC, bgp_static);
	}

	bgp_dest_unlock_node(dest);
	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Removed IPv4 multicast network %s from AS %u",
			  prefix_str, bgp->as);


	return NB_OK;
}

