/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/afi-safis/afi-safi/ipv6-multicast/aggregate-route
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv6_multicast_aggregate_route_create(struct nb_cb_create_args *args)
{
	struct bgp *bgp;
	const char *prefix_str;
	struct prefix p;
	struct bgp_dest *dest;
	struct bgp_aggregate *aggregate;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	/* lyd_parent to skip stale entry stored at this dnode on delta re-commit; see 993754e18a */
	bgp = nb_running_get_entry(lyd_parent(args->dnode), NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	/* Create aggregate table if it doesn't exist */
	if (!bgp->aggregate[AFI_IP6][SAFI_MULTICAST])
		bgp->aggregate[AFI_IP6][SAFI_MULTICAST] =
			bgp_table_init(bgp, AFI_IP6, SAFI_MULTICAST);

	prefix_str = yang_dnode_get_string(args->dnode, "./prefix");
	if (str2prefix(prefix_str, &p) == 0)
		return NB_ERR_VALIDATION;
	apply_mask(&p);

	dest = bgp_node_get(bgp->aggregate[AFI_IP6][SAFI_MULTICAST], &p);
	aggregate = bgp_dest_get_bgp_aggregate_info(dest);

	if (!aggregate) {
		aggregate = XCALLOC(MTYPE_BGP_AGGREGATE,
				    sizeof(struct bgp_aggregate));
		aggregate->origin = BGP_ORIGIN_UNSPECIFIED;
		bgp_dest_set_bgp_aggregate_info(dest, aggregate);
	}

	nb_running_set_entry(args->dnode, aggregate);

	/* Build the aggregate route */
	bgp_aggregate_route(bgp, &p, AFI_IP6, SAFI_MULTICAST, aggregate);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Created IPv6 multicast aggregate-address %s on AS %u",
			  prefix_str, bgp->as);


	return NB_OK;
}


int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv6_multicast_aggregate_route_destroy(struct nb_cb_destroy_args *args)
{
	struct bgp *bgp;
	const char *prefix_str;
	struct prefix p;
	struct bgp_dest *dest;
	struct bgp_aggregate *aggregate;
	const struct lyd_node *bgp_dnode;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	/*
	 * Get the aggregate from this node's running entry,
	 * then get BGP from the parent bgp node.
	 */
	aggregate = nb_running_get_entry(args->dnode, NULL, false);

	bgp_dnode = yang_dnode_get_parent(args->dnode, "bgp");
	if (!bgp_dnode)
		return NB_OK;

	bgp = nb_running_get_entry(bgp_dnode, NULL, true);
	if (!bgp)
		return NB_OK;

	/* Check if aggregate table exists */
	if (!bgp->aggregate[AFI_IP6][SAFI_MULTICAST])
		return NB_OK;

	prefix_str = yang_dnode_get_string(args->dnode, "./prefix");
	if (str2prefix(prefix_str, &p) == 0)
		return NB_OK;
	apply_mask(&p);

	dest = bgp_node_lookup(bgp->aggregate[AFI_IP6][SAFI_MULTICAST], &p);
	if (!dest)
		return NB_OK;

	if (aggregate) {
		bgp_aggregate_delete(bgp, &p, AFI_IP6, SAFI_MULTICAST,
				     aggregate);
		bgp_aggregate_install(bgp, AFI_IP6, SAFI_MULTICAST, &p, 0,
				      NULL, NULL, NULL, NULL, 0,
				      aggregate);
		bgp_dest_set_bgp_aggregate_info(dest, NULL);
		bgp_aggregate_free(aggregate);
	}

	nb_running_unset_entry(args->dnode);
	bgp_dest_unlock_node(dest);
	bgp_dest_unlock_node(dest);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Removed IPv6 multicast aggregate-address %s from AS %u",
			  prefix_str, bgp->as);


	return NB_OK;
}

