/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/neighbors/neighbor/solo
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_neighbor_solo_modify(struct nb_cb_modify_args *args)
{
	struct peer *peer;
	bool solo;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	peer = nb_running_get_entry(args->dnode, NULL, true);
	if (!peer)
		return NB_ERR_NOT_FOUND;

	solo = yang_dnode_get_bool(args->dnode, NULL);
	/*
	 * update_group_adjust_soloness() sets PEER_FLAG_LONESOUL AND
	 * pulls the peer out of its shared update group so its
	 * outbound advertisements are filtered. Baseline's
	 * DEFUN(neighbor_solo) calls this — not peer_flag_set() — so
	 * without it the flag flips but the peer stays in the shared
	 * group and still receives advertisements.
	 */
	update_group_adjust_soloness(peer, solo ? 1 : 0);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Set solo=%s for neighbor %s",
			  solo ? "true" : "false", peer->host);


	return NB_OK;
}


