/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/neighbors/neighbor/update-source/ip
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_neighbor_update_source_ip_modify(struct nb_cb_modify_args *args)
{
	struct peer *peer;
	const char *ip_str;
	union sockunion su;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	peer = nb_running_get_entry(args->dnode, NULL, true);
	if (!peer)
		return NB_ERR_NOT_FOUND;

	ip_str = yang_dnode_get_string(args->dnode, NULL);
	if (str2sockunion(ip_str, &su) < 0)
		return NB_ERR_VALIDATION;

	peer_update_source_addr_set(peer, &su);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Set update-source %s for neighbor %s",
			  ip_str, peer->host);


	return NB_OK;
}


int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_neighbor_update_source_ip_destroy(struct nb_cb_destroy_args *args)
{
	struct peer *peer;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	peer = nb_running_get_entry(args->dnode, NULL, true);
	if (!peer)
		return NB_OK;

	peer_update_source_unset(peer);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Removed update-source from neighbor %s", peer->host);


	return NB_OK;
}

/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/neighbors/neighbor/update-source/interface
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_neighbor_update_source_interface_modify(struct nb_cb_modify_args *args)
{
	struct peer *peer;
	const char *ifname;
	int ret;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	peer = nb_running_get_entry(args->dnode, NULL, true);
	if (!peer)
		return NB_ERR_NOT_FOUND;

	ifname = yang_dnode_get_string(args->dnode, NULL);
	ret = peer_update_source_if_set(peer, ifname);
	if (ret != 0) {
		if (BGP_DEBUG(northbound, NORTHBOUND))
			zlog_debug("[BGP-NB] Failed to set update-source interface %s for neighbor %s",
				  ifname, peer->host);
		return NB_ERR_RESOURCE;
	}

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Set update-source interface %s for neighbor %s",
			  ifname, peer->host);


	return NB_OK;
}


int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_neighbor_update_source_interface_destroy(struct nb_cb_destroy_args *args)
{
	struct peer *peer;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	peer = nb_running_get_entry(args->dnode, NULL, true);
	if (!peer)
		return NB_OK;

	peer_update_source_unset(peer);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Removed update-source interface from neighbor %s",
			  peer->host);


	return NB_OK;
}

