/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/neighbors/neighbor/afi-safis/afi-safi/l2vpn-evpn/as-path-options/allow-own-as
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_neighbor_afi_safis_afi_safi_l2vpn_evpn_as_path_options_allow_own_as_modify(struct nb_cb_modify_args *args)
{
	struct peer *peer;
	uint8_t allow_num;

	switch (args->event) {
	case NB_EV_VALIDATE:
	case NB_EV_PREPARE:
	case NB_EV_ABORT:
		break;
	case NB_EV_APPLY:
		peer = nb_running_get_entry(args->dnode, "../../../../..", true);
		if (!peer)
			return NB_ERR_NOT_FOUND;

		allow_num = yang_dnode_get_uint8(args->dnode, NULL);

		/* Guard: during NB commit, peer may not be fully initialized.
		 * peer_allowas_in_set → peer_on_policy_change dereferences
		 * peer->connection which may be NULL. Just set the flag.
		 */
		if (!peer->connection) {
			SET_FLAG(peer->af_flags[AFI_L2VPN][SAFI_EVPN],
				 PEER_FLAG_ALLOWAS_IN);
			peer->allowas_in[AFI_L2VPN][SAFI_EVPN] = allow_num;
			break;
		}

		peer_allowas_in_set(peer, AFI_L2VPN, SAFI_EVPN, allow_num, 0);

		if (BGP_DEBUG(northbound, NORTHBOUND))
			zlog_debug("[BGP-NB] Set EVPN neighbor %s allow-own-as=%u",
				  peer->host, allow_num);
		break;
	}

	return NB_OK;
}


int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_neighbor_afi_safis_afi_safi_l2vpn_evpn_as_path_options_allow_own_as_destroy(struct nb_cb_destroy_args *args)
{
	struct peer *peer;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	peer = nb_running_get_entry(args->dnode, "../../../../..", true);
	if (!peer)
		return NB_ERR_NOT_FOUND;

	peer_allowas_in_unset(peer, AFI_L2VPN, SAFI_EVPN);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Unset EVPN neighbor %s allow-own-as",
			  peer->host);


	return NB_OK;
}

/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/neighbors/neighbor/afi-safis/afi-safi/l2vpn-evpn/as-path-options/allow-own-origin-as
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_neighbor_afi_safis_afi_safi_l2vpn_evpn_as_path_options_allow_own_origin_as_modify(struct nb_cb_modify_args *args)
{
	struct peer *peer;
	bool enable;

	switch (args->event) {
	case NB_EV_VALIDATE:
	case NB_EV_PREPARE:
	case NB_EV_ABORT:
		break;
	case NB_EV_APPLY:
		peer = nb_running_get_entry(args->dnode, "../../../../..", true);
		if (!peer)
			return NB_ERR_NOT_FOUND;

		enable = yang_dnode_get_bool(args->dnode, NULL);

		if (!peer->connection) {
			if (enable) {
				SET_FLAG(peer->af_flags[AFI_L2VPN][SAFI_EVPN],
					 PEER_FLAG_ALLOWAS_IN);
				SET_FLAG(peer->af_flags[AFI_L2VPN][SAFI_EVPN],
					 PEER_FLAG_ALLOWAS_IN_ORIGIN);
			}
			break;
		}

		if (enable)
			peer_allowas_in_set(peer, AFI_L2VPN, SAFI_EVPN, 0, 1);
		else
			peer_allowas_in_unset(peer, AFI_L2VPN, SAFI_EVPN);

		if (BGP_DEBUG(northbound, NORTHBOUND))
			zlog_debug("[BGP-NB] Set EVPN neighbor %s allow-own-origin-as=%s",
				  peer->host, enable ? "true" : "false");
		break;
	}

	return NB_OK;
}


