/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/neighbors/unnumbered-neighbor
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_unnumbered_neighbor_create(struct nb_cb_create_args *args)
{
	struct bgp *bgp;
	const char *interface_name;
	struct peer *peer;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	/* Start lookup at parent; see neighbor_create for rationale. */
	bgp = nb_running_get_entry(lyd_parent(args->dnode), NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	interface_name = yang_dnode_get_string(args->dnode, "./interface");

	/* Check if peer already exists */
	peer = peer_lookup_by_conf_if(bgp, interface_name);
	if (!peer) {
		/* Create interface-based peer with AS_UNSPECIFIED.
		 * AS will be set via remote-as callback.
		 * Pass NULL for su and interface_name for conf_if.
		 */
		peer = peer_create(NULL, interface_name, bgp, bgp->as, 0,
				   AS_UNSPECIFIED, NULL, true, NULL, UNKNOWN);
		if (!peer) {
			if (BGP_DEBUG(northbound, NORTHBOUND))
				zlog_debug("[BGP-NB] Failed to create unnumbered neighbor %s",
					  interface_name);
			return NB_ERR_RESOURCE;
		}

		/*
		 * Baseline `neighbor WORD interface [peer-group]` always
		 * initiates IPv6 RA on the interface and enables the
		 * extended-nexthop (ENHE) capability as soon as the peer
		 * is created, so that peering works regardless of whether
		 * IPv4 addresses appear later. The NB callback must mirror
		 * that — without it, `show interface` reports
		 * bgpRAConfigured=false and ND-RA never gets sent, breaking
		 * unnumbered BGP peering.
		 *
		 * Call unconditionally — baseline (bgp_vty.c
		 * peer_conf_interface_get) does the same.  If peer->ifp
		 * isn't set yet (the test's interface hasn't reached
		 * zebra's view at create time), bgp_zebra_initiate_radv
		 * falls into bgp_nht_reg_enhe_cap_intfs which is safe
		 * (returns early without a valid sockunion).  The real RA
		 * setup happens later via bgp_ifp_create →
		 * bgp_update_interface_nbrs when the interface arrives.
		 */
		bgp_zebra_initiate_radv(bgp, peer);

		if (!CHECK_FLAG(peer->flags_invert,
				PEER_FLAG_CAPABILITY_ENHE)) {
			SET_FLAG(peer->flags, PEER_FLAG_CAPABILITY_ENHE);
			SET_FLAG(peer->flags_invert,
				 PEER_FLAG_CAPABILITY_ENHE);
			SET_FLAG(peer->flags_override,
				 PEER_FLAG_CAPABILITY_ENHE);
		}
	}

	nb_running_set_entry(args->dnode, peer);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Created unnumbered neighbor %s on AS %u",
			  interface_name, bgp->as);


	return NB_OK;
}


int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_unnumbered_neighbor_destroy(struct nb_cb_destroy_args *args)
{
	struct peer *peer;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	peer = nb_running_unset_entry(args->dnode);
	if (!peer)
		return NB_OK;

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Destroying unnumbered neighbor %s",
			  peer->host);

	/* See numbered neighbor destroy for why we pair
	 * terminate_radv + notify_unconfig + peer_delete. Unnumbered
	 * neighbors always have peer->ifp set, so always terminate RA.
	 */
	if (peer->ifp ||
	    CHECK_FLAG(peer->flags, PEER_FLAG_CAPABILITY_ENHE))
		bgp_zebra_terminate_radv(peer->bgp, peer);
	peer_notify_unconfig(peer->connection);
	peer_delete(peer);


	return NB_OK;
}

