/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/neighbors/unnumbered-neighbor/peer-group
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_unnumbered_neighbor_peer_group_modify(struct nb_cb_modify_args *args)
{
	if (args->event != NB_EV_APPLY)
		return NB_OK;

	
	{
	struct bgp *bgp;
	struct peer *peer;
	struct peer_group *group;
	const char *group_name;
	as_t as;

	peer = nb_running_get_entry(args->dnode, NULL, true);
	if (!peer)
		return NB_ERR_NOT_FOUND;

	bgp = peer->bgp;
	group_name = yang_dnode_get_string(args->dnode, NULL);
	group = peer_group_lookup(bgp, group_name);
	if (!group)
		return NB_ERR_NOT_FOUND;

	as = peer->as;
	/* Clear NB_PENDING_CONFIG BEFORE peer_group_bind — see
	 * remote-as-type/modify for rationale. */
	UNSET_FLAG(peer->sflags, PEER_STATUS_NB_PENDING_CONFIG);
	peer_group_bind(bgp, &peer->connection->su, peer, group, &as);

	return NB_OK;
	}


	return NB_OK;
}


int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_unnumbered_neighbor_peer_group_destroy(struct nb_cb_destroy_args *args)
{
	struct peer *peer;
	struct peer_group *group;
	struct bgp *bgp;
	int ret;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	peer = nb_running_get_entry(args->dnode, NULL, true);
	if (!peer)
		return NB_ERR_NOT_FOUND;

	/* Must be in a peer-group to unbind */
	if (!peer->group) {
		if (BGP_DEBUG(northbound, NORTHBOUND))
			zlog_debug("[BGP-NB] Unnumbered peer %s not in a peer-group, nothing to unbind",
				   peer->host);
		return NB_OK;
	}

	bgp = peer->bgp;
	group = peer->group;

	ret = peer_group_unbind(bgp, peer, group);
	if (ret != 0) {
		if (BGP_DEBUG(northbound, NORTHBOUND))
			zlog_debug("[BGP-NB] Failed to unbind unnumbered neighbor %s from peer-group %s: %d",
				   peer->host, group->name, ret);
		return NB_ERR_RESOURCE;
	}

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Unbound unnumbered neighbor %s from peer-group %s",
			   peer->host, group->name);

	/* See neighbor_peer_group_destroy for rationale. */
	if (!yang_dnode_exists(args->dnode,
			       "../neighbor-remote-as/remote-as-type"))
		SET_FLAG(peer->sflags,
			 PEER_STATUS_NB_PENDING_CONFIG);


	return NB_OK;
}

/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/neighbors/unnumbered-neighbor/neighbor-remote-as/remote-as-type
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_unnumbered_neighbor_neighbor_remote_as_remote_as_type_modify(struct nb_cb_modify_args *args)
{
	struct peer *peer;
	const char *as_type_str;
	enum peer_asn_type as_type;
	as_t as = 0;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	peer = nb_running_get_entry(args->dnode, NULL, true);
	if (!peer)
		return NB_ERR_NOT_FOUND;

	as_type_str = yang_dnode_get_string(args->dnode, NULL);

	/* Map YANG as-type to internal enum */
	if (strcmp(as_type_str, "internal") == 0) {
		as_type = AS_INTERNAL;
	} else if (strcmp(as_type_str, "external") == 0) {
		as_type = AS_EXTERNAL;
	} else if (strcmp(as_type_str, "as-specified") == 0) {
		as_type = AS_SPECIFIED;
		/* Read sibling remote-as value if it exists */
		if (yang_dnode_exists(args->dnode, "../remote-as")) {
			as = yang_dnode_get_uint32(args->dnode, "../remote-as");
			/* Use the numeric AS string for as_pretty,
			 * not the type name "as-specified".
			 */
			as_type_str = yang_dnode_get_string(
				args->dnode, "../remote-as");
		} else {
			/* AS value not yet set, will be handled by remote-as callback */
			return NB_OK;
		}
	} else if (strcmp(as_type_str, "auto") == 0) {
		as_type = AS_AUTO;
	} else {
		if (BGP_DEBUG(northbound, NORTHBOUND))
			zlog_debug("[BGP-NB] Unknown as-type for unnumbered neighbor: %s", as_type_str);
		return NB_ERR_VALIDATION;
	}

	/* Clear NB_PENDING_CONFIG BEFORE peer_as_change — see
	 * remote-as-type/modify for rationale. */
	UNSET_FLAG(peer->sflags, PEER_STATUS_NB_PENDING_CONFIG);

	/* Update peer AS type */
	peer_as_change(peer, as, as_type, as_type_str);

	/* For AS_EXTERNAL/AS_INTERNAL/AS_AUTO (where as=0),
	 * peer_as_change() incorrectly sets local_as to confed_id
	 * because it checks !bgp_confederation_peers_check(bgp, 0)
	 * which is always true. Correct local_as here.
	 */
	if (as == 0 && CHECK_FLAG(peer->bgp->config, BGP_CONFIG_CONFEDERATION))
		peer->local_as = peer->bgp->as;

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Set unnumbered neighbor %s remote-as type to %s",
			  peer->host, as_type_str);


	return NB_OK;
}


int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_unnumbered_neighbor_neighbor_remote_as_remote_as_type_destroy(struct nb_cb_destroy_args *args)
{
	struct peer *peer;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	peer = nb_running_get_entry(args->dnode, NULL, false);
	if (!peer)
		return NB_OK;
	if (!peer_group_active(peer))
		SET_FLAG(peer->sflags, PEER_STATUS_NB_PENDING_CONFIG);


	return NB_OK;
}

/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/neighbors/unnumbered-neighbor/neighbor-remote-as/remote-as
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_unnumbered_neighbor_neighbor_remote_as_remote_as_modify(struct nb_cb_modify_args *args)
{
	struct peer *peer;
	as_t as;
	char as_str[32];

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	peer = nb_running_get_entry(args->dnode, NULL, true);
	if (!peer)
		return NB_ERR_NOT_FOUND;

	as = yang_dnode_get_uint32(args->dnode, NULL);
	snprintf(as_str, sizeof(as_str), "%u", as);

	/* Clear NB_PENDING_CONFIG BEFORE peer_as_change — see
	 * remote-as-type/modify for rationale. */
	UNSET_FLAG(peer->sflags, PEER_STATUS_NB_PENDING_CONFIG);

	/* Update peer AS */
	peer_as_change(peer, as, AS_SPECIFIED, as_str);

	/* Ensure listening socket exists for this VRF */
	bgp_start_listening(peer->bgp);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Set remote-as %u for unnumbered neighbor %s",
			  as, peer->host);


	return NB_OK;
}


