/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/neighbors/unnumbered-neighbor/local-as/local-as
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_unnumbered_neighbor_local_as_local_as_modify(struct nb_cb_modify_args *args)
{
	struct peer *peer;
	as_t as;
	bool no_prepend = false;
	bool replace_as = false;
	bool dual_as = false;
	const char *as_str;

	switch (args->event) {
	case NB_EV_VALIDATE: {
		as_t bgp_as;
		as = yang_dnode_get_uint32(args->dnode, NULL);
		bgp_as = yang_dnode_get_uint32(args->dnode,
			"../../../../global/local-as");
		if (as == bgp_as) {
			snprintf(args->errmsg, args->errmsg_len,
				 "Cannot have local-as same as BGP AS number");
			return NB_ERR_VALIDATION;
		}
		break;
	}
	case NB_EV_PREPARE:
	case NB_EV_ABORT:
		break;
	case NB_EV_APPLY:
		peer = nb_running_get_entry(args->dnode, NULL, true);
		if (!peer)
			return NB_ERR_NOT_FOUND;

		as = yang_dnode_get_uint32(args->dnode, NULL);
		as_str = yang_dnode_get_string(args->dnode, NULL);

		/* Get sibling no-prepend, replace-as, and dual-as values */
		if (yang_dnode_exists(args->dnode, "../no-prepend"))
			no_prepend = yang_dnode_get_bool(args->dnode, "../no-prepend");
		if (yang_dnode_exists(args->dnode, "../replace-as"))
			replace_as = yang_dnode_get_bool(args->dnode, "../replace-as");
		if (yang_dnode_exists(args->dnode, "../dual-as"))
			dual_as = yang_dnode_get_bool(args->dnode, "../dual-as");

		peer_local_as_set(peer, as, no_prepend, replace_as, dual_as, as_str);
		break;
	}

	return NB_OK;
}


int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_unnumbered_neighbor_local_as_local_as_destroy(struct nb_cb_destroy_args *args)
{
	struct peer *peer;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	peer = nb_running_get_entry(args->dnode, NULL, true);
	if (!peer)
		return NB_ERR_NOT_FOUND;

	peer_local_as_unset(peer);


	return NB_OK;
}

/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/neighbors/unnumbered-neighbor/local-as/no-prepend
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_unnumbered_neighbor_local_as_no_prepend_modify(struct nb_cb_modify_args *args)
{
	struct peer *peer;
	bool no_prepend;
	bool replace_as;

	switch (args->event) {
	case NB_EV_VALIDATE:
	case NB_EV_PREPARE:
	case NB_EV_ABORT:
		break;
	case NB_EV_APPLY:
		peer = nb_running_get_entry(args->dnode, NULL, true);
		if (!peer)
			return NB_ERR_NOT_FOUND;

		/* Only update if local-as is already set */
		if (!peer->change_local_as)
			break;

		no_prepend = yang_dnode_get_bool(args->dnode, NULL);
		replace_as = !!CHECK_FLAG(peer->flags, PEER_FLAG_LOCAL_AS_REPLACE_AS);

		peer_local_as_set(peer, peer->change_local_as, no_prepend,
				  replace_as,
				  yang_dnode_exists(args->dnode, "../dual-as") ?
				  yang_dnode_get_bool(args->dnode, "../dual-as") : false,
				  peer->change_local_as_pretty);
		break;
	}

	return NB_OK;
}


/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/neighbors/unnumbered-neighbor/local-as/replace-as
 */
