/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/neighbors/unnumbered-neighbor/graceful-restart/graceful-restart-disable
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_unnumbered_neighbor_graceful_restart_graceful_restart_disable_modify(struct nb_cb_modify_args *args)
{
	struct peer *peer;
	bool disable;
	int ret = BGP_GR_SUCCESS;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	peer = nb_running_get_entry(args->dnode, NULL, true);
	if (!peer)
		return NB_ERR_NOT_FOUND;

	disable = yang_dnode_get_bool(args->dnode, NULL);

	if (disable)
		bgp_neighbor_graceful_restart(peer, PEER_DISABLE_CMD);
	else
		bgp_neighbor_graceful_restart(peer, NO_PEER_DISABLE_CMD);

	if (peer->bgp->t_startup || bgp_in_graceful_restart())
		bgp_peer_gr_flags_update(peer);

	VTY_BGP_GR_ROUTER_DETECT_AND_SEND_CAPABILITY_TO_ZEBRA(
		peer->bgp, peer->bgp->peer, ret);
	(void)ret;


	return NB_OK;
}


int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_unnumbered_neighbor_graceful_restart_graceful_restart_disable_destroy(struct nb_cb_destroy_args *args)
{
	struct peer *peer;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	peer = nb_running_get_entry(args->dnode, NULL, true);
	if (!peer)
		return NB_ERR_NOT_FOUND;

	{
	int ret = BGP_GR_SUCCESS;

	/* Use the GR FSM to remove the disable and return to global inherit */
	bgp_neighbor_graceful_restart(peer, NO_PEER_DISABLE_CMD);

	VTY_BGP_GR_ROUTER_DETECT_AND_SEND_CAPABILITY_TO_ZEBRA(
		peer->bgp, peer->bgp->peer, ret);
	(void)ret;
	}


	return NB_OK;
}

