{
	if (args->event != NB_EV_APPLY)
		return NB_OK;

	
	{
	struct peer *peer;
	afi_t afi;
	safi_t safi;

	peer = nb_running_get_entry(args->dnode, NULL, true);
	if (!peer)
		return NB_ERR_NOT_FOUND;

	yang_afi_safi_identity2value(yang_dnode_get_string(args->dnode, "../../afi-safi-name"), &afi, &safi);

	if (yang_dnode_get_bool(args->dnode, NULL))
		peer_af_flag_set(peer, afi, safi, PEER_FLAG_SOFT_RECONFIG);
	else
		peer_af_flag_unset(peer, afi, safi, PEER_FLAG_SOFT_RECONFIG);
	return NB_OK;
	}


	return NB_OK;
}


