/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/peer-groups/peer-group
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_peer_groups_peer_group_create(struct nb_cb_create_args *args)
{
	struct bgp *bgp;
	const char *peer_group_name;
	struct peer_group *group;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	/* Start lookup at parent; see neighbor_create for rationale. */
	bgp = nb_running_get_entry(lyd_parent(args->dnode), NULL, true);
	if (!bgp)
		return NB_ERR_NOT_FOUND;

	peer_group_name = yang_dnode_get_string(args->dnode, "./peer-group-name");

	group = peer_group_get(bgp, peer_group_name);
	if (!group) {
		if (BGP_DEBUG(northbound, NORTHBOUND))
			zlog_debug("[BGP-NB] Failed to create peer-group %s",
				  peer_group_name);
		return NB_ERR_RESOURCE;
	}

	nb_running_set_entry(args->dnode, group);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Created peer-group %s on AS %u",
			  peer_group_name, bgp->as);


	return NB_OK;
}


int routing_control_plane_protocols_control_plane_protocol_bgp_peer_groups_peer_group_destroy(struct nb_cb_destroy_args *args)
{
	struct peer_group *group;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	group = nb_running_unset_entry(args->dnode);
	if (!group)
		return NB_OK;

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Destroying peer-group %s", group->name);

	{
		struct bgp *bgp_parent = group->bgp;

		peer_group_delete(group);
		/*
		 * If this was the last peer-group/peer with any
		 * listen range and there are no remaining peers,
		 * release the VRF-bound listening socket.  Mirrors
		 * baseline's bgp_may_stop_listening() at DEFUN exit.
		 */
		bgp_stop_listening_if_empty(bgp_parent);
	}


	return NB_OK;
}

/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/peer-groups/peer-group/ipv4-listen-range
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_peer_groups_peer_group_ipv4_listen_range_create(struct nb_cb_create_args *args)
{
	struct peer_group *group;
	struct prefix range;
	const char *prefix_str;
	int ret;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	group = nb_running_get_entry(args->dnode, NULL, true);
	if (!group)
		return NB_ERR_NOT_FOUND;

	prefix_str = yang_dnode_get_string(args->dnode, NULL);
	if (str2prefix(prefix_str, &range) == 0)
		return NB_ERR_VALIDATION;

	/*
	 * Due to northbound callback ordering, the listen-range
	 * callback may run before the remote-as callback. Check if
	 * remote-as exists in the YANG tree and apply it first.
	 */
	if (group->conf->as_type == AS_UNSPECIFIED) {
		const char *as_type_str;
		as_t as = 0;
		enum peer_asn_type as_type = AS_UNSPECIFIED;

		if (yang_dnode_exists(args->dnode,
				      "../neighbor-remote-as/remote-as-type")) {
			as_type_str = yang_dnode_get_string(
				args->dnode,
				"../neighbor-remote-as/remote-as-type");
			if (strcmp(as_type_str, "internal") == 0) {
				as_type = AS_INTERNAL;
			} else if (strcmp(as_type_str, "external") == 0) {
				as_type = AS_EXTERNAL;
			} else if (strcmp(as_type_str, "as-specified") == 0) {
				as_type = AS_SPECIFIED;
				if (yang_dnode_exists(args->dnode,
						      "../neighbor-remote-as/remote-as"))
					as = yang_dnode_get_uint32(
						args->dnode,
						"../neighbor-remote-as/remote-as");
			}

			if (as_type != AS_UNSPECIFIED) {
				peer_group_remote_as(group->bgp, group->name,
						     &as, as_type, NULL);
			}
		}
	}

	/* Ensure listening socket is created */
	bgp_start_listening(group->bgp);

	ret = peer_group_listen_range_add(group, &range);
	if (ret != 0) {
		snprintf(args->errmsg, args->errmsg_len,
			 "Failed to add listen range %s to peer-group %s (ret=%d)",
			 prefix_str, group->name, ret);
		return NB_ERR_RESOURCE;
	}

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Added IPv4 listen range %s to peer-group %s",
			  prefix_str, group->name);


	return NB_OK;
}


int routing_control_plane_protocols_control_plane_protocol_bgp_peer_groups_peer_group_ipv4_listen_range_destroy(struct nb_cb_destroy_args *args)
{
	struct peer_group *group;
	struct prefix range;
	const char *prefix_str;
	int ret;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	group = nb_running_get_entry(args->dnode, NULL, true);
	if (!group)
		return NB_OK;

	prefix_str = yang_dnode_get_string(args->dnode, NULL);
	if (str2prefix(prefix_str, &range) == 0)
		return NB_OK;

	ret = peer_group_listen_range_del(group, &range);
	if (ret != 0) {
		if (BGP_DEBUG(northbound, NORTHBOUND))
			zlog_debug("[BGP-NB] Failed to delete IPv4 listen range %s from peer-group %s",
				  prefix_str, group->name);
	}

	/* Close socket if no more listen ranges or peers */
	bgp_stop_listening_if_empty(group->bgp);

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Deleted IPv4 listen range %s from peer-group %s",
			  prefix_str, group->name);


	return NB_OK;
}

