int routing_control_plane_protocols_control_plane_protocol_bgp_peer_groups_peer_group_neighbor_remote_as_remote_as_destroy(struct nb_cb_destroy_args *args)
{
	/* The AS number is only valid when remote-as-type is "as-specified".
	 * Removing the AS number without removing the type doesn't make sense,
	 * so the cleanup should happen via remote-as-type destroy.
	 */
	switch (args->event) {
	case NB_EV_VALIDATE:
	case NB_EV_PREPARE:
	case NB_EV_ABORT:
		break;
	case NB_EV_APPLY:
		break;
	}

	return NB_OK;
}

