/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/peer-groups/peer-group/local-as/local-as
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_peer_groups_peer_group_local_as_local_as_modify(struct nb_cb_modify_args *args)
{
	struct peer_group *group;
	struct peer *peer;
	as_t as;
	bool no_prepend = false;
	bool replace_as = false;
	bool dual_as = false;
	const char *as_str;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	group = nb_running_get_entry(args->dnode, NULL, true);
	if (!group)
		return NB_ERR_NOT_FOUND;

	peer = group->conf;
	as = yang_dnode_get_uint32(args->dnode, NULL);
	as_str = yang_dnode_get_string(args->dnode, NULL);

	/* Get sibling no-prepend, replace-as, and dual-as values */
	if (yang_dnode_exists(args->dnode, "../no-prepend"))
		no_prepend = yang_dnode_get_bool(args->dnode, "../no-prepend");
	if (yang_dnode_exists(args->dnode, "../replace-as"))
		replace_as = yang_dnode_get_bool(args->dnode, "../replace-as");
	if (yang_dnode_exists(args->dnode, "../dual-as"))
		dual_as = yang_dnode_get_bool(args->dnode, "../dual-as");

	peer_local_as_set(peer, as, no_prepend, replace_as, dual_as, as_str);


	return NB_OK;
}


int routing_control_plane_protocols_control_plane_protocol_bgp_peer_groups_peer_group_local_as_local_as_destroy(struct nb_cb_destroy_args *args)
{
	struct peer_group *group;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	group = nb_running_get_entry(args->dnode, NULL, true);
	if (!group)
		return NB_ERR_NOT_FOUND;

	peer_local_as_unset(group->conf);


	return NB_OK;
}

/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/peer-groups/peer-group/local-as/no-prepend
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_peer_groups_peer_group_local_as_no_prepend_modify(struct nb_cb_modify_args *args)
{
	struct peer_group *group;
	struct peer *peer;
	bool no_prepend;
	bool replace_as;

	switch (args->event) {
	case NB_EV_VALIDATE:
	case NB_EV_PREPARE:
	case NB_EV_ABORT:
		break;
	case NB_EV_APPLY:
		group = nb_running_get_entry(args->dnode, NULL, true);
		if (!group)
			return NB_ERR_NOT_FOUND;

		peer = group->conf;

		/* Only update if local-as is already set */
		if (!peer->change_local_as)
			break;

		no_prepend = yang_dnode_get_bool(args->dnode, NULL);
		replace_as = !!CHECK_FLAG(peer->flags, PEER_FLAG_LOCAL_AS_REPLACE_AS);

		peer_local_as_set(peer, peer->change_local_as, no_prepend,
				  replace_as,
				  yang_dnode_exists(args->dnode, "../dual-as") ?
				  yang_dnode_get_bool(args->dnode, "../dual-as") : false,
				  peer->change_local_as_pretty);
		break;
	}

	return NB_OK;
}


