/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/peer-groups/peer-group/graceful-restart/graceful-restart-disable
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_peer_groups_peer_group_graceful_restart_graceful_restart_disable_modify(struct nb_cb_modify_args *args)
{
	struct peer_group *group;
	bool disable;
	int ret = BGP_GR_SUCCESS;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	group = nb_running_get_entry(args->dnode, NULL, true);
	if (!group)
		return NB_ERR_NOT_FOUND;

	disable = yang_dnode_get_bool(args->dnode, NULL);

	if (disable)
		bgp_neighbor_graceful_restart(group->conf,
					      PEER_DISABLE_CMD);
	else
		bgp_neighbor_graceful_restart(group->conf,
					      NO_PEER_DISABLE_CMD);

	if (group->conf->bgp->t_startup || bgp_in_graceful_restart())
		bgp_peer_gr_flags_update(group->conf);

	VTY_BGP_GR_ROUTER_DETECT_AND_SEND_CAPABILITY_TO_ZEBRA(
		group->conf->bgp, group->conf->bgp->peer, ret);
	(void)ret;


	return NB_OK;
}


