/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/peer-groups/peer-group/timers/hold-time
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_peer_groups_peer_group_timers_hold_time_modify(struct nb_cb_modify_args *args)
{
	struct peer_group *group;
	struct peer *peer;
	uint32_t holdtime;
	uint32_t keepalive;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	group = nb_running_get_entry(args->dnode, NULL, true);
	if (!group)
		return NB_ERR_NOT_FOUND;

	peer = group->conf;
	holdtime = yang_dnode_get_uint16(args->dnode, NULL);
	/*
	 * keepalive=0 and holdtime=0 are valid configured values per
	 * baseline peer_timers_set — they disable BGP keepalive while
	 * keeping PEER_FLAG_TIMER set, which BFD strict mode inspects.
	 * `no neighbor X timers` uses NB_OP_DESTROY to really clear
	 * the flag (via the destroy callback), not a MODIFY=0.
	 */
	keepalive = peer->keepalive ? peer->keepalive : holdtime / 3;
	peer_timers_set(peer, keepalive, holdtime);


	return NB_OK;
}


/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/peer-groups/peer-group/timers/keepalive
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_peer_groups_peer_group_timers_keepalive_modify(struct nb_cb_modify_args *args)
{
	struct peer_group *group;
	struct peer *peer;
	uint32_t keepalive;
	uint32_t holdtime;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	group = nb_running_get_entry(args->dnode, NULL, true);
	if (!group)
		return NB_ERR_NOT_FOUND;

	peer = group->conf;
	keepalive = yang_dnode_get_uint16(args->dnode, NULL);
	/* See hold-time modify — keepalive=0 is a valid configured
	 * value. `no neighbor X timers` goes through DESTROY.
	 */
	holdtime = peer->holdtime ? peer->holdtime : keepalive * 3;
	peer_timers_set(peer, keepalive, holdtime);


	return NB_OK;
}


