	/* Get peer-group from xpath: enabled -> afi-safi -> afi-safis -> peer-group */
	group = nb_running_get_entry(args->dnode, "../../..", true);
	if (!group)
		return NB_ERR_NOT_FOUND;

	/* Get AFI/SAFI from the afi-safi-name key */
	afi_safi_name = yang_dnode_get_string(args->dnode, "../afi-safi-name");
	yang_afi_safi_identity2value(afi_safi_name, &afi, &safi);

	/* Deactivate the peer-group in this AFI/SAFI */
	peer_deactivate(group->conf, afi, safi);


	return NB_OK;
