/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/peer-groups/peer-group/afi-safis/afi-safi/addpath-rx-paths-limit
 */
int bgp_peer_groups_peer_group_afi_safi_addpath_rx_paths_limit_modify(struct nb_cb_modify_args *args)
{
	struct peer_group *group;
	const char *afi_safi_name;
	afi_t afi;
	safi_t safi;
	uint16_t limit;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	group = nb_running_get_entry(args->dnode, "../../..", true);
	if (!group)
		return NB_ERR_NOT_FOUND;

	afi_safi_name = yang_dnode_get_string(args->dnode, "../afi-safi-name");
	yang_afi_safi_identity2value(afi_safi_name, &afi, &safi);

	limit = yang_dnode_get_uint16(args->dnode, NULL);

	peer_af_flag_set(group->conf, afi, safi, PEER_FLAG_ADDPATH_RX_PATHS_LIMIT);
	group->conf->addpath_paths_limit[afi][safi].send = limit;


	return NB_OK;
}

int bgp_peer_groups_peer_group_afi_safi_addpath_rx_paths_limit_destroy(struct nb_cb_destroy_args *args)
{
	struct peer_group *group;
	const char *afi_safi_name;
	afi_t afi;
	safi_t safi;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	group = nb_running_get_entry(args->dnode, "../../..", true);
	if (!group)
		return NB_ERR_NOT_FOUND;

	afi_safi_name = yang_dnode_get_string(args->dnode, "../afi-safi-name");
	yang_afi_safi_identity2value(afi_safi_name, &afi, &safi);

	peer_af_flag_unset(group->conf, afi, safi, PEER_FLAG_ADDPATH_RX_PATHS_LIMIT);
	group->conf->addpath_paths_limit[afi][safi].send = 0;


	return NB_OK;
}

