int routing_control_plane_protocols_control_plane_protocol_bgp_peer_groups_peer_group_afi_safis_afi_safi_ipv4_unicast_encapsulation_modify(struct nb_cb_modify_args *args)
{
	struct peer_group *peer_group;
	int encap;

	switch (args->event) {
	case NB_EV_VALIDATE:
	case NB_EV_PREPARE:
	case NB_EV_ABORT:
		return NB_OK;
	case NB_EV_APPLY:
		peer_group = nb_running_get_entry(args->dnode, "../../../../..", true);
		if (!peer_group)
			return NB_ERR_NOT_FOUND;

		encap = yang_dnode_get_enum(args->dnode, NULL);
		/* Clear both flags first */
		peer_af_flag_unset(peer_group->conf, AFI_IP, SAFI_UNICAST, PEER_FLAG_CONFIG_ENCAPSULATION_SRV6);
		peer_af_flag_unset(peer_group->conf, AFI_IP, SAFI_UNICAST, PEER_FLAG_CONFIG_ENCAPSULATION_MPLS);
		/* Set the appropriate flag based on encapsulation type */
		peer_af_flag_unset(peer_group->conf, AFI_IP, SAFI_UNICAST, PEER_FLAG_CONFIG_ENCAPSULATION_SRV6_RELAX);
		if (encap == 1) /* srv6 */
			peer_af_flag_set(peer_group->conf, AFI_IP, SAFI_UNICAST, PEER_FLAG_CONFIG_ENCAPSULATION_SRV6);
		else if (encap == 2) /* mpls */
			peer_af_flag_set(peer_group->conf, AFI_IP, SAFI_UNICAST, PEER_FLAG_CONFIG_ENCAPSULATION_MPLS);
		else if (encap == 3) /* srv6-relax */
			peer_af_flag_set(peer_group->conf, AFI_IP, SAFI_UNICAST, PEER_FLAG_CONFIG_ENCAPSULATION_SRV6_RELAX);
		return NB_OK;
	}

	return NB_OK;
}

