/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/peer-groups/peer-group/afi-safis/afi-safi/l2vpn-evpn/as-path-options/allow-own-as
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_peer_groups_peer_group_afi_safis_afi_safi_l2vpn_evpn_as_path_options_allow_own_as_modify(struct nb_cb_modify_args *args)
{
	struct peer_group *group;
	struct peer *peer;
	uint8_t allow_num;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	group = nb_running_get_entry(args->dnode, "../../../../..", true);
	if (!group)
		return NB_ERR_NOT_FOUND;

	peer = group->conf;
	allow_num = yang_dnode_get_uint8(args->dnode, NULL);

	/* During NB commit, peer-group members may not be fully
	 * initialized (no connection). Set flags directly on conf
	 * peer — members inherit when bound via peer_group_bind().
	 */
	SET_FLAG(peer->af_flags[AFI_L2VPN][SAFI_EVPN],
		 PEER_FLAG_ALLOWAS_IN);
	peer->allowas_in[AFI_L2VPN][SAFI_EVPN] = allow_num;

	if (BGP_DEBUG(northbound, NORTHBOUND))
		zlog_debug("[BGP-NB] Set EVPN peer-group %s allow-own-as=%u",
			  peer->host, allow_num);


	return NB_OK;
}


