/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/peer-groups/peer-group/local-role/role
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_peer_groups_peer_group_local_role_role_modify(struct nb_cb_modify_args *args)
{
	struct peer_group *group;
	struct peer *peer;
	const char *role_str;
	uint8_t role;
	bool strict_mode;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	group = nb_running_get_entry(args->dnode, NULL, true);
	if (!group)
		return NB_ERR_NOT_FOUND;

	peer = group->conf;
	role_str = yang_dnode_get_string(args->dnode, NULL);
	if (strcmp(role_str, "provider") == 0)
		role = ROLE_PROVIDER;
	else if (strcmp(role_str, "rs-server") == 0)
		role = ROLE_RS_SERVER;
	else if (strcmp(role_str, "rs-client") == 0)
		role = ROLE_RS_CLIENT;
	else if (strcmp(role_str, "customer") == 0)
		role = ROLE_CUSTOMER;
	else if (strcmp(role_str, "peer") == 0)
		role = ROLE_PEER;
	else
		return NB_ERR_VALIDATION;

	strict_mode = yang_dnode_get_bool(args->dnode, "../strict-mode");
	peer_role_set(peer, role, strict_mode);

	bgp_capability_send(peer->connection, AFI_IP, SAFI_UNICAST,
			    CAPABILITY_CODE_ROLE,
			    CAPABILITY_ACTION_SET);


	return NB_OK;
}

int routing_control_plane_protocols_control_plane_protocol_bgp_peer_groups_peer_group_local_role_role_destroy(struct nb_cb_destroy_args *args)
{
	struct peer_group *group;
	struct peer *peer;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	group = nb_running_get_entry(args->dnode, NULL, true);
	if (!group)
		return NB_ERR_NOT_FOUND;

	peer = group->conf;
	peer_role_unset(peer);

	bgp_capability_send(peer->connection, AFI_IP, SAFI_UNICAST,
			    CAPABILITY_CODE_ROLE,
			    CAPABILITY_ACTION_UNSET);


	return NB_OK;
}

