/* neighbors/neighbor accept-own callbacks */
int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_neighbor_afi_safis_afi_safi_l3vpn_ipv4_unicast_accept_own_modify(struct nb_cb_modify_args *args)
{
	struct peer *peer;
	FILE *dbg;

	/* DEBUG: Write to file to bypass logging issues */
	dbg = fopen("/tmp/accept_own_callback.log", "a");
	if (dbg) {
		fprintf(dbg, "accept-own callback invoked, event=%d\n", args->event);
		fflush(dbg);
	}

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	if (dbg) {
		fprintf(dbg, "NB_EV_APPLY: getting peer from dnode\n");
		fflush(dbg);
	}
	zlog_warn("BGP-NB: accept-own (l3vpn-ipv4) callback INVOKED, event=NB_EV_APPLY");
	peer = nb_running_get_entry(args->dnode, "../../../..", true);
	if (!peer) {
		if (dbg) {
			fprintf(dbg, "ERROR: peer NOT FOUND!\n");
			fclose(dbg);
		}
		zlog_warn("BGP-NB: accept-own - peer NOT FOUND via nb_running_get_entry!");
		return NB_ERR_NOT_FOUND;
	}

	if (dbg) {
		fprintf(dbg, "Found peer %s, setting flag, value=%d\n",
			peer->host, yang_dnode_get_bool(args->dnode, NULL));
		fprintf(dbg, "  peer->connection=%p, peer_established=%d\n",
			(void *)peer->connection,
			peer->connection ? peer_established(peer->connection) : -1);
		fflush(dbg);
	}
	zlog_warn("BGP-NB: accept-own - found peer %s, value=%d",
		   peer->host, yang_dnode_get_bool(args->dnode, NULL));
	if (yang_dnode_get_bool(args->dnode, NULL))
		peer_af_flag_set(peer, AFI_IP, SAFI_MPLS_VPN, PEER_FLAG_ACCEPT_OWN);
	else
		peer_af_flag_unset(peer, AFI_IP, SAFI_MPLS_VPN, PEER_FLAG_ACCEPT_OWN);
	if (dbg) {
		fprintf(dbg, "Flag set complete, PEER_FLAG_ACCEPT_OWN=%d\n",
			CHECK_FLAG(peer->af_flags[AFI_IP][SAFI_MPLS_VPN], PEER_FLAG_ACCEPT_OWN) ? 1 : 0);
	}
	zlog_warn("BGP-NB: accept-own - flag set complete");

	if (dbg)
		fclose(dbg);
	return NB_OK;
}

int routing_control_plane_protocols_control_plane_protocol_bgp_neighbors_neighbor_afi_safis_afi_safi_l3vpn_ipv6_unicast_accept_own_modify(struct nb_cb_modify_args *args)
{
	struct peer *peer;

	if (args->event != NB_EV_APPLY)
		return NB_OK;

	peer = nb_running_get_entry(args->dnode, "../../../..", true);
	if (!peer)
		return NB_ERR_NOT_FOUND;

	if (yang_dnode_get_bool(args->dnode, NULL))
		peer_af_flag_set(peer, AFI_IP6, SAFI_MPLS_VPN, PEER_FLAG_ACCEPT_OWN);
	else
		peer_af_flag_unset(peer, AFI_IP6, SAFI_MPLS_VPN, PEER_FLAG_ACCEPT_OWN);

	return NB_OK;
}

