/*
 * Generic no-op callbacks for dampening parameter leaves
 * (half-life, reuse-threshold, suppress-threshold, max-suppress-time)
 *
 * These leaves have their values stored in YANG and are read when
 * dampening/enable is set to true. The actual application is done
 * in the enable callback.
 */
int bgp_dampening_param_modify(struct nb_cb_modify_args *args)
{
	/* Values are applied when enable=true via helper function */
	return NB_OK;
}

int bgp_dampening_param_destroy(struct nb_cb_destroy_args *args)
{
	/* Values are reset when enable=false via helper function */
	return NB_OK;
}

