/*
 * Advertise-map helper functions for conditional advertisement
 */
static int bgp_nb_peer_advertise_map_modify_internal(struct nb_cb_modify_args *args,
                                                     const char *peer_xpath,
                                                     afi_t afi, safi_t safi,
                                                     bool is_peer_group)
{
    switch (args->event) {
    case NB_EV_VALIDATE:
    case NB_EV_PREPARE:
    case NB_EV_ABORT:
        break;
    case NB_EV_APPLY: {
        const char *advertise_name, *condition_name, *condition_type_str;
        struct peer *peer;
        bool condition;
        struct route_map *advertise_map = NULL, *condition_map = NULL;

        /* Check if all sibling leaves are set */
        if (!yang_dnode_exists(args->dnode, "../advertise-map-name") ||
            !yang_dnode_exists(args->dnode, "../condition-map-name") ||
            !yang_dnode_exists(args->dnode, "../condition-type"))
            break;

        peer = nb_running_get_entry(args->dnode, peer_xpath, true);
        if (!peer)
            return NB_ERR_NOT_FOUND;

        advertise_name = yang_dnode_get_string(args->dnode, "../advertise-map-name");
        condition_name = yang_dnode_get_string(args->dnode, "../condition-map-name");
        condition_type_str = yang_dnode_get_string(args->dnode, "../condition-type");

        condition = (strcmp(condition_type_str, "exist-map") == 0);

        advertise_map = route_map_lookup_by_name(advertise_name);
        condition_map = route_map_lookup_by_name(condition_name);

        peer_advertise_map_set(peer, afi, safi, advertise_name, advertise_map,
                               condition_name, condition_map, condition);
        break;
    }
    }
    return NB_OK;
}

/* Leaf type enum for advertise-map destroy callback */
enum advertise_map_leaf {
    ADVERTISE_MAP_LEAF_NAME,
    ADVERTISE_MAP_LEAF_CONDITION_NAME,
    ADVERTISE_MAP_LEAF_CONDITION_TYPE,
};

static int bgp_nb_peer_advertise_map_destroy_internal(struct nb_cb_destroy_args *args,
                                                      const char *peer_xpath,
                                                      afi_t afi, safi_t safi,
                                                      bool is_peer_group,
                                                      enum advertise_map_leaf leaf)
{
    switch (args->event) {
    case NB_EV_VALIDATE:
    case NB_EV_PREPARE:
    case NB_EV_ABORT:
        break;
    case NB_EV_APPLY: {
        struct peer *peer;

        /* Only unset when the advertise-map-name leaf is destroyed */
        if (leaf != ADVERTISE_MAP_LEAF_NAME)
            break;

        peer = nb_running_get_entry(args->dnode, peer_xpath, true);
        if (!peer)
            return NB_ERR_NOT_FOUND;

        peer_advertise_map_unset(peer, afi, safi, NULL, NULL, NULL, NULL, 0);
        break;
    }
    }
    return NB_OK;
}

